(110, 'JO ISI MAP BANK MEGA', '<p>	Bahan : Manila merk Tjiwi</p><p>	Misal:</p><p>	Order 1000</p><p>	Beli bahan 900 plano ukuran plano 86x61 cm</p><p>	Potong jadi 5, ukuran 25x34 cm</p><p>	&nbsp;</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/JO%20isi%20Map%20BANK%20MEGA%2021%20jan%202014.jpg\" style=\"width: 700px; height: 492px;\" /></p><p>	____________________________________________________________________________________________________</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/jo%20isi%20map%20bank%20Mega.jpg\" style=\"width: 700px; height: 492px;\" /></p><p>	____________________________________________________________________________________________________</p><p>	Dummy cetakan Bank Mega</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/dummy%20cetakan%20bank%20mega.jpg\" style=\"width: 700px; height: 933px;\" /></p>', 'setting', NULL, NULL, 2, 0, 3);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(111, 'JO MAP KREDIT PENSIUN', '<p>	<strong><span style=\"font-size:14px;\"><span style=\"font-family:trebuchet ms,helvetica,sans-serif;\">Map 47x35 cm (terbuka)</span></span></strong></p><p>	<span style=\"font-size:14px;\"><span style=\"font-family:trebuchet ms,helvetica,sans-serif;\">Bahan </span></span></p><p>	<span style=\"font-size:14px;\"><span style=\"font-family:trebuchet ms,helvetica,sans-serif;\">&nbsp; - Buffalo krem tekstur jeruk, </span></span></p><p>	<span style=\"font-size:14px;\"><span style=\"font-family:trebuchet ms,helvetica,sans-serif;\">&nbsp; - plano 108x79 cm, 1 plano jadi 4, ukuran potong 50x36 cm.</span></span></p><p>	&nbsp; - potong plano 50x36 cm, kalo order 1000, planonya 285, + kuping 72 plano</p><p>	&nbsp; - cetak 2 muka, 1 warna hitam.</p><p>	&nbsp; - kuping potong plano jadi 16 ukuran potong 27x19 cm.</p><p>	&nbsp; - kebutuhan bahan kuping kihat stok di mujib.</p><p>	<span style=\"font-size:14px;\"><span style=\"font-family:trebuchet ms,helvetica,sans-serif;\">Area cetakan lihat gambar di bawah.</span></span></p><p>	<span style=\"font-size:14px;\"><span style=\"font-family:trebuchet ms,helvetica,sans-serif;\">Atau lihat&nbsp;D:\\koperasi aliansi sejahtera\\2012\\map\\kredit pensiun\\post set\\aturan cetak map kredit pensiun.jpg</span></span></p><p>	&nbsp;</p><p>	<span style=\"font-size:14px;\"><span style=\"font-family:trebuchet ms,helvetica,sans-serif;\">Bahan untuk <strong>Kuping</strong></span></span></p><p>	<span style=\"font-size:14px;\"><span style=\"font-family:trebuchet ms,helvetica,sans-serif;\">1 plano jadi 16, ukuran potong 27x19 cm</span></span></p><p>	&nbsp;</p><p>	<span style=\"font-size:14px;\"><span style=\"font-family:trebuchet ms,helvetica,sans-serif;\">Aturan cetak Map</span></span></p><p>	<span style=\"font-size:14px;\"><span style=\"font-family:trebuchet ms,helvetica,sans-serif;\"><img alt=\"\" src=\"/project/pb/gambar/images/aturan%20cetak%20map%20kredit%20pensiun.jpg\" style=\"width: 1000px; height: 726px; \" /></span></span></p><p>	&nbsp;</p><p>	<span style=\"font-size:14px;\"><span style=\"font-family:trebuchet ms,helvetica,sans-serif;\"><img alt=\"\" src=\"/project/pb/gambar/images/JO%20Map%20Kredit%20pensiun.jpg\" style=\"width: 700px; height: 492px; border-width: 1px; border-style: solid;\" /></span></span></p>', 'setting', NULL, NULL, 2, 0, 3),
(112, 'JO DSE (Tempat Kartu & Katalog DSE)', '<p>	<strong><u>JO tempat Kartu DSE</u></strong></p><p>	Order = 10.000, bahan plano 100x65 = 295 pcs potong jadi 6</p><p>	ukuran 10,4 x 14,5 cm, kertas AP 210 gr, offset 1 muka, 1 warna</p><p>	Potong = 32,5 x 33 cm</p><p>	area cetak = 32 x 30 cm</p><p>	pond L 29</p><p>	&nbsp;</p><p>	<strong><u>Amplop DSE &amp; Cover Katalog</u></strong></p><p>	Amplop DSE dicetak bareng dengan cover katalog (buat stok)</p><p>	File yg dipake terakhir yg 2 mata, untuk optimasi bahan.</p><p>	Macam macam plano Art Carton yg dipake (109x79, 61x92, 65x90, 65x100 cm)</p><p>	posisi file:&nbsp;rutin\\dse\\2013\\amplop+cover katalog</p><p>	&nbsp;</p><p>	<strong><u>Layout setting katalog DSE</u></strong></p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/seting%20katalog%20DSE(1).jpg\" style=\"width: 900px; height: 783px;\" /><img alt=\"\" src=\"/project/pb/gambar/images/format%20layout%20buku%20katalog%20DSE.jpg\" style=\"width: 267px; height: 700px;\" /></p><p>	<strong>Format Lipat Isi Katalog DSE di mesin lipat:</strong></p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/1_%202013-03-08%2014_56_39.jpg\" style=\"width: 333px; height: 200px;\" /></p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/2_%202013-03-08%2014_57_01.jpg\" style=\"width: 333px; height: 200px;\" /></p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/3_%202013-03-08%2014_58_30.jpg\" style=\"width: 300px; height: 500px;\" /></p><p>	&nbsp;</p>', 'setting', NULL, NULL, 2, 0, 3),
(113, 'JO OFFSET (tidak berlaku indigo) UNDANGAN RSHS', '<p>\r\n	ISI</p>\r\n<ul>\r\n	<li>\r\n		ukuran Jadi\r\n		<ul>\r\n			<li>\r\n				isi &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;= A5</li>\r\n			<li>\r\n				amplop &nbsp;= 215x150 mm</li>\r\n		</ul>\r\n	</li>\r\n	<li>\r\n		Order&nbsp;<strong>300 pcs</strong></li>\r\n	<li>\r\n		area cetak 31 x 45 cm. 1 area jadi 4</li>\r\n	<li>\r\n		Plano&nbsp;108x79 cm, <strong>19 pcs</strong></li>\r\n	<li>\r\n		potong jadi 5, ukuran 33 x 45 cm</li>\r\n</ul>\r\n<p>\r\n	AMPLOP</p>\r\n<ul>\r\n	<li>\r\n		ukuran jadi&nbsp;215x150 mm</li>\r\n	<li>\r\n		<strong>order 300</strong></li>\r\n	<li>\r\n		area cetak 245x326 mm. 1 area jadi 1</li>\r\n	<li>\r\n		Plano 108x79 cm, <strong>49 pcs</strong></li>\r\n	<li>\r\n		potong jadi 8, ukuran 27 x 39,5 cm</li>\r\n</ul>\r\n', 'setting', NULL, NULL, 2, 0, 3),
(114, 'JO BOX SI KRITING', '<p>\r\n	&nbsp;</p>\r\n<ul>\r\n	<li>\r\n		Bahan\r\n		<ul>\r\n			<li>\r\n				&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;duplex 310 gr, 108 x 79 cm</li>\r\n			<li>\r\n				&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;potong jadi 6, ukuran = 36 x 39,5 cm</li>\r\n		</ul>\r\n	</li>\r\n	<li>\r\n		Cetakan\r\n		<ul>\r\n			<li>\r\n				&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;area cetak = 34 x 39,5 cm</li>\r\n			<li>\r\n				&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;1 muka, 1 warna orange</li>\r\n		</ul>\r\n	</li>\r\n	<li>\r\n		Finish\r\n		<ul>\r\n			<li>\r\n				&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;tanpa laminasi</li>\r\n			<li>\r\n				&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;pond</li>\r\n		</ul>\r\n	</li>\r\n</ul>\r\n', 'setting', NULL, NULL, 2, 0, 3),
(115, 'JO PAPER BAG PUPUK KUJANG', '<p>\r\n	order 500 pcs, ukuran 22 x 10,5 x 34 cm, kertas samsons, cetak 1 warna (hitam), tali kur emas</p>\r\n<p>\r\n	&nbsp;</p>\r\n<p>\r\n	Bahan: Samsons 120 x 90 cm 130 gr (bahan 200 pcs), potong jadi 6, ukuran 45 x36 cm</p>\r\n<p>\r\n	film 45x36 cm.&nbsp;</p>\r\n<p>\r\n	&nbsp;</p>\r\n<p>\r\n	mesin harus 52</p>\r\n', 'setting', NULL, NULL, 2, 0, 3),
(116, 'Cara Instalasi Photocopy Canon IR 3570/4570 PCL5e', '<p>\r\n	&nbsp;</p>\r\n<div>\r\n	<span style=\"font-size:14px;\"><span style=\"font-family:trebuchet ms,helvetica,sans-serif;\">Cara Install Photocopy</span></span></div>\r\n<div>\r\n	<span style=\"font-size:14px;\"><span style=\"font-family:trebuchet ms,helvetica,sans-serif;\">1. Start - Device and Printer - Add Printer</span></span></div>\r\n<div>\r\n	<span style=\"font-size:14px;\"><span style=\"font-family:trebuchet ms,helvetica,sans-serif;\">2. Pilih Canon IR 3570/4570 PCL5e - Next</span></span></div>\r\n<div>\r\n	<span style=\"font-size:14px;\"><span style=\"font-family:trebuchet ms,helvetica,sans-serif;\">3. lalu muncul Browse - Pilih File di </span></span></div>\r\n<div>\r\n	<span style=\"font-size:14px;\"><span style=\"font-family:trebuchet ms,helvetica,sans-serif;\">\\\\SERVER\\installer\\Driver\\photocopy\\driver iR series\\driver iR series\\AutoPlay\\Docs\\Printer\\win2k_vista\\pcl5e_5c</span></span></div>\r\n<div>\r\n	<span style=\"font-size:14px;\"><span style=\"font-family:trebuchet ms,helvetica,sans-serif;\">4. Next - Tunggu sampai instalasi Selesai</span></span></div>\r\n', 'administrasi', NULL, NULL, 2, 0, 7),
(117, 'Banner, X Banner, roll banner, spanduk', '<p>\r\n	1. Save as file desain menjadi jpeg.</p>\r\n<p>\r\n	2. buka file jpeg di Photoshop.</p>\r\n<p>\r\n	3. Cross cek ukuran file dengan ukuran di project.</p>\r\n<p>\r\n	4. Tekan <strong>Ctrl+Alt+i </strong>, lalu perhatikan kotak dialog:</p>\r\n<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/pixel%20dimention.jpg\" style=\"width: 446px; height: 360px;\" /></p>\r\n<p>\r\n	Keterangan (lihat yg di blok ungu):&nbsp;</p>\r\n<p>\r\n	a. <strong>Pixel Dimention</strong> = maksimal adalah 150 MB, cara adjustment-nya adalah dgn cara:</p>\r\n<p>\r\n	- &nbsp;<strong>Width &amp; High</strong> sesuaikan&nbsp;dengan ukuran banner sebenarnya (sesuai project)</p>\r\n<p>\r\n	- ubah naikkan / turunkan <strong>Resolution</strong>&nbsp;hingga angka Pixel Dimention mendekati 150 MB.</p>\r\n<p>\r\n	5. save as ke jpg lagi, samakan data ini: Quality 8, Format Progressive.</p>\r\n<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/save%20as%20jpeg%20progressive.jpg\" style=\"width: 342px; height: 304px;\" /></p>\r\n<p>\r\n	6. klik OK, selesai<br />\r\n	<br />\r\n	<br />\r\n	&nbsp;</p>\r\n<table align=\"center\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"width: 500px\">\r\n	<thead>\r\n		<tr>\r\n			<th scope=\"col\">\r\n				<span style=\"font-size:14px;\">x(cm)</span></th>\r\n			<th scope=\"col\">\r\n				<span style=\"font-size:14px;\">y(cm)</span></th>\r\n			<th scope=\"col\">\r\n				<p>\r\n					<span style=\"font-size:14px;\">Resolusi (dpi)</span></p>\r\n			</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"text-align: center;\">\r\n				50</td>\r\n			<td style=\"text-align: center;\">\r\n				100</td>\r\n			<td style=\"text-align: center;\">\r\n				<strong>260</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">\r\n				<span style=\"color:#ff0000;\">60</span></td>\r\n			<td style=\"text-align: center;\">\r\n				<span style=\"color:#ff0000;\">160</span></td>\r\n			<td style=\"text-align: center;\">\r\n				<span style=\"color:#ff0000;\">187</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">\r\n				100</td>\r\n			<td style=\"text-align: center;\">\r\n				100</td>\r\n			<td style=\"text-align: center;\">\r\n				<strong>183</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">\r\n				150</td>\r\n			<td style=\"text-align: center;\">\r\n				100</td>\r\n			<td style=\"text-align: center;\">\r\n				<strong>150</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">\r\n				250</td>\r\n			<td style=\"text-align: center;\">\r\n				75</td>\r\n			<td style=\"text-align: center;\">\r\n				<strong>134</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">\r\n				200</td>\r\n			<td style=\"text-align: center;\">\r\n				100</td>\r\n			<td style=\"text-align: center;\">\r\n				<strong>130</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">\r\n				250</td>\r\n			<td style=\"text-align: center;\">\r\n				100</td>\r\n			<td style=\"text-align: center;\">\r\n				<strong>116</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">\r\n				300</td>\r\n			<td style=\"text-align: center;\">\r\n				100</td>\r\n			<td style=\"text-align: center;\">\r\n				<strong>106</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">\r\n				350</td>\r\n			<td style=\"text-align: center;\">\r\n				100</td>\r\n			<td style=\"text-align: center;\">\r\n				<strong>98</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">\r\n				400</td>\r\n			<td style=\"text-align: center;\">\r\n				100</td>\r\n			<td style=\"text-align: center;\">\r\n				<strong>91</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align: center;\">\r\n				450</td>\r\n			<td style=\"text-align: center;\">\r\n				100</td>\r\n			<td style=\"text-align: center;\">\r\n				<strong>86</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-alig