(235, 'Order CS ke AR', '<p>\r\n	format order ke AR via Whatsapp:</p>\r\n<div>\r\n	Nama :</div>\r\n<div>\r\n	HP :</div>\r\n<div>\r\n	Email : &nbsp;</div>\r\n<div>\r\n	Alamat :</div>\r\n<div>\r\n	Order :</div>\r\n<div>\r\n	Spek :</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	harga :</div>\r\n<div>\r\n	DP : sudah / belum&nbsp;</div>\r\n<div>\r\n	Deal dengan klien :</div>\r\n', 'marketing', NULL, NULL, 2, 0, 4);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(236, 'form pengiriman dari sanggar (Z:\\setting\\percetakan bandung\\form pengiriman)', '<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/pengiriman(1).jpg\" style=\"width: 1600px; height: 1101px;\" /></p>\r\n', 'finishing', NULL, NULL, 2, 0, 12),
(237, 'JADWAL ', '<p style=\"margin-left:1.0in;\">\r\n	-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; uang makan karyawan, Rp.20.000,-/org tiap hari sabtu&nbsp;</p>\r\n<p style=\"margin-left:1.0in;\">\r\n	-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; dana csr PB ke tafio foundation tiap tgl 10 / bulan</p>\r\n<p style=\"margin-left:1.0in;\">\r\n	-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; iuran PB ke tafio (bulanan, listrik, internet, kontrakan, dll) tiap tgl 10 / bulan</p>\r\n<p style=\"margin-left:1.0in;\">\r\n	-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; tagihan desain bulan sebelumnya tiap tgl 25 / bulan</p>\r\n<p style=\"margin-left:1.0in;\">\r\n	-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; tagihan central uv bulan sebelumnya tiap tgl 25 / bulan</p>\r\n<p style=\"margin-left:1.0in;\">\r\n	-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; melakukan pengarsipan data transaksi di rekening bank (bcas, muammalat dan bsm) tiap tgl 1 / bulan&nbsp;</p>\r\n<p style=\"margin-left:1.0in;\">\r\n	-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; bayar tagihan telepon kembar dan sanggar tiap tgl 15 / bulan</p>\r\n', 'keuangan', NULL, NULL, 2, 0, 5),
(238, 'NAME TAG A6 (95x135)', '<p>\r\n	- Ukuran plastik name tag A6 = 103x162 mm (sisi terluar)<span id=\"cke_bm_106S\" style=\"display: none;\">&nbsp;</span><span style=\"display: none;\">&nbsp;</span></p>\r\n<p>\r\n	<span style=\"color:#000000;\">- kertas maksimal yg bisa masuk = 98x140 mm&nbsp;</span><span style=\"color: rgb(0, 0, 0);\">(jadi 8 mata di indigo) (versi dulu) &gt; </span><strong style=\"color: rgb(0, 0, 0);\">udah gak dipake&nbsp;</strong></p>\r\n<p>\r\n	<span style=\"color:#000000;\"><strong><span id=\"cke_bm_106E\" style=\"display: none;\">&nbsp;</span></strong></span></p>\r\n<p>\r\n	<span style=\"display: none;\">&nbsp;</span></p>\r\n<p>\r\n	<strong>- revisi terbaru, ukuran kertas name tag = 95x135 mm (jadi 9 mata di indigo) (10/11/2016)</strong></p>\r\n', 'cetak', NULL, NULL, 2, 0, 10),
(239, 'Uang tips', '<div>\r\n	mengingat masih maraknya &#39;&#39;UANG TIPS&#39;&#39; dikalangan kita</div>\r\n<div>\r\n	untuk itu kami dari management percetakan bandung menegaskan&nbsp;</div>\r\n<div>\r\n	bahwa uang tips atau suap dan lain sebagainya hukumnya tidak di bolehkan.</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	seperti sabda rosulullah salllahu alaihi wassalam</div>\r\n<div>\r\n	dari Abu Humaid As Sa&rsquo;idiy. Rasulullah shallallahu &lsquo;alaihi wa sallam bersabda,</div>\r\n<div>\r\n	&ldquo;Hadiah bagi pejabat / pekerja adalah ghulul / khianat.</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	melihat dari sabda rosul tsb yang harus kita lakukan adalah</div>\r\n<div>\r\n	#MENERIMA UANG TIPS&nbsp;</div>\r\n<div>\r\n	1. menolak dengan cara ahsan uang tips atau suap dan yang lain jenisnya</div>\r\n<div>\r\n	2. jika klien memaksa untuk kita menerimanya (klien akan tersinggung marah ngamuk ngambek dll)</div>\r\n<div>\r\n	&nbsp; &nbsp;maka terimalah uang tips tsb dan mintalah keikhlasan dan keridhoan uang tsb dri klien .</div>\r\n<div>\r\n	3. uang tips akan dikumpulkan dalam suatu kotak yang telah disediakan.</div>\r\n<div>\r\n	4. jika uang tips sdh terkumpul anggap dibuka setengah tahun sekali,</div>\r\n<div>\r\n	&nbsp; &nbsp; &nbsp;uang tips yg sdh di ikhlaskan oleh klien akan di peruntukkan sebagai kepentingan bersama contohnya&nbsp;</div>\r\n<div>\r\n	&nbsp; &nbsp; &nbsp;buat beli makanan</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	#MEMBERI UANG TIPS</div>\r\n<div>\r\n	1. TIDAK MEMBERIKAN uang tips kepada pekerja lain selama pekerja lain tsb masih mengerjakan kerjaan.</div>\r\n<div>\r\n	2. management akan memberi sosialisasi kepada management rekanan untuk di tiadakannya uang tips.&nbsp;</div>\r\n<div>\r\n	3. BERI UANG TIPS jika sudah mulai mengancam pekerjaan (kerjaan tidak dikerjakan, di lama lamain, dlsb)</div>\r\n<div>\r\n	&nbsp; &nbsp;sesuai kesepakatan management dan management rekanan.</div>\r\n', 'peraturan', NULL, NULL, NULL, 1, 14),
(240, 'DIGITAL PRINTING', '<p>\r\n	<span style=\"font-size:14px;\"><span style=\"font-family:arial,helvetica,sans-serif;\"><strong>harga Jasa Print Bandung:</strong></span></span></p>\r\n<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:847px;\" width=\"847\">\r\n	<colgroup>\r\n		<col />\r\n		<col />\r\n		<col />\r\n		<col />\r\n		<col />\r\n	</colgroup>\r\n	<tbody>\r\n		<tr height=\"24\">\r\n			<td height=\"24\" style=\"height:24px;width:47px;\">\r\n				No<span id=\"cke_bm_105S\" style=\"display: none;\">&nbsp;</span><span style=\"display: none;\">&nbsp;</span></td>\r\n			<td style=\"width:228px;\">\r\n				BAHAN</td>\r\n			<td style=\"width:101px;\">\r\n				JUMLAH</td>\r\n			<td style=\"width:123px;\">\r\n				HPP /muka</td>\r\n			<td style=\"width:348px;\">\r\n				<span style=\"color:#ff0000;\">HARGA JUAL SATUAN 1 - 5 L<span style=\"display: none;\">&nbsp;</span><span id=\"cke_bm_105E\" style=\"display: none;\">&nbsp;</span>EMBAR</span></td>\r\n		</tr>\r\n		<tr height=\"21\">\r\n			<td height=\"63\" rowspan=\"3\" style=\"height:63px;\">\r\n				1</td>\r\n			<td rowspan=\"3\">\r\n				AC 190/210/230/260</td>\r\n			<td>\r\n				1&nbsp; -&nbsp; 300</td>\r\n			<td>\r\n				&nbsp;</td>\r\n			<td rowspan=\"3\">\r\n				ikut harga express</td>\r\n		</tr>\r\n		<tr height=\"21\">\r\n			<td height=\"21\" style=\"height:21px;\">\r\n				301&nbsp; -&nbsp; 500</td>\r\n			<td>\r\n				&nbsp;</td>\r\n		</tr>\r\n		<tr height=\"21\">\r\n			<td height=\"21\" style=\"height:21px;\">\r\n				501&nbsp; -&nbsp; dst</td>\r\n			<td>\r\n				&nbsp;</td>\r\n		</tr>\r\n		<tr height=\"21\">\r\n			<td height=\"63\" rowspan=\"3\" style=\"height:63px;\">\r\n				2</td>\r\n			<td rowspan=\"3\">\r\n				AP/MP/HVS 80/100/120/150</td>\r\n			<td>\r\n				1&nbsp; -&nbsp; 300</td>\r\n			<td>\r\n				&nbsp;</td>\r\n			<td rowspan=\"3\">\r\n				ikut harga express</td>\r\n		</tr>\r\n		<tr height=\"21\">\r\n			<td height=\"21\" style=\"height:21px;\">\r\n				301&nbsp; -&nbsp; 500</td>\r\n			<td>\r\n				&nbsp;</td>\r\n		</tr>\r\n		<tr height=\"21\">\r\n			<td height=\"21\" style=\"height:21px;\">\r\n				501&nbsp; -&nbsp; dst</td>\r\n			<td>\r\n				&nbsp;</td>\r\n		</tr>\r\n		<tr height=\"21\">\r\n			<td height=\"63\" rowspan=\"3\" style=\"height:63px;\">\r\n				3</td>\r\n			<td rowspan=\"3\">\r\n				BW/Concord/AC 310</td>\r\n			<td>\r\n				1&nbsp; -&nbsp; 300</td>\r\n			<td>\r\n				&nbsp;</td>\r\n			<td rowspan=\"3\">\r\n				ikut harga express</td>\r\n		</tr>\r\n		<tr height=\"21\">\r\n			<td height=\"21\" style=\"height:21px;\">\r\n				301&nbsp; -&nbsp; 500</td>\r\n			<td>\r\n				R</td>\r\n		</tr>\r\n		<tr height=\"21\">\r\n			<td height=\"21\" style=\"height:21px;\">\r\n				501&nbsp; -&nbsp; dst</td>\r\n			<td>\r\n				&nbsp;</td>\r\n		</tr>\r\n		<tr height=\"21\">\r\n			<td height=\"63\" rowspan=\"3\" style=\"height:63px;\">\r\n				4</td>\r\n			<td rowspan=\"3\">\r\n				Stiker chromo</td>\r\n			<td>\r\n				1&nbsp; -&nbsp; 300</td>\r\n			<td>\r\n				R</td>\r\n			<td rowspan=\"3\">\r\n				Rp 15.000</td>\r\n		</tr>\r\n		<tr height=\"21\">\r\n			<td height=\"21\" style=\"height:21px;\">\r\n				301&nbsp; -&nbsp; 500</td>\r\n			<td>\r\n				&nbsp;</td>\r\n		</tr>\r\n		<tr height=\"21\">\r\n			<td height=\"21\" style=\"height:21px;\">\r\n				501&nbsp; -&nbsp; dst</td>\r\n			<td>\r\n				&nbsp;</td>\r\n		</tr>\r\n		<tr height=\"21\">\r\n			<td height=\"63\" rowspan=\"3\" style=\"height:63px;\">\r\n				5</td>\r\n			<td rowspan=\"3\">\r\n				Stiker Vinyl / transparan</td>\r\n			<td>\r\n				1&nbsp; -&nbsp; 300</td>\r\n			<td>\r\n				&nbsp;</td>\r\n			<td rowspan=\"3\">\r\n				Rp 25.000</td>\r\n		</tr>\r\n		<tr height=\"21\">\r\n			<td height=\"21\" style=\"height:21px;\">\r\n				301&nbsp; -&nbsp; 500</td>\r\n			<td>\r\n				&nbsp;</td>\r\n		</tr>\r\n		<tr height=\"21\">\r\n			<td height=\"21\" style=\"height:21px;\">\r\n				501&nbsp; -&nbsp; dst</td>\r\n			<td>\r\n				&nbsp;</td>\r\n		</tr>\r\n		<tr height=\"21\">\r\n			<td height=\"63\" rowspan=\"3\" style=\"height:63px;\">\r\n				6</td>\r\n			<td rowspan=\"3\">\r\n				Laminasi doff/gloss</td>\r\n			<td>\r\n				1&nbsp; - 100</td>\r\n			<td>\r\n				&nbsp;</td>\r\n			<td rowspan=\"3\">\r\n				Rp 2.500</td>\r\n		</tr>\r\n		<tr height=\"21\">\r\n			<td height=\"21\" style=\"height:21px;\">\r\n				100 - 200</td>\r\n			<td>\r\n				&nbsp;</td>\r\n		</tr>\r\n		<tr height=\"21\">\r\n			<td height=\"21\" style=\"height:21px;\">\r\n				&gt;200</td>\r\n			<td>\r\n				&nbsp;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<p>\r\n	&nbsp;</p>\r\n<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"width: 847px;\" width=\"847\">\r\n	<tbody>\r\n		<tr height=\"21\">\r\n			<td>\r\n				kalau ada klien bandingkan dengan harga pagarsih atau dapat harga yang sama dengan hpp jasa print<br />\r\n				&nbsp;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<p>\r\n	kasih HPPnya, nanti langsung kontak ke :</p>\r\n<p>\r\n	Jasa Print Bandung</p>\r\n<p>\r\n	Jamil&nbsp;+62 857-2243-4186</p>\r\n<p>\r\n	<span style=\"color:#ff0000;\">HPP jasaprint hanya cetak tanpa potong</span><br />\r\n	&nbsp;</p>\r\n<div>\r\n	cetak satuan harganya pakai sop pricelist tambahan, ketentuan tambahan :</div>\r\n<div>\r\n	- produksi akan langsung print (pastikan file sudah bagus dan tidak ada yang salah ejaan)</div>\r\n<div>\r\n	- tidak ada konfirmasi (revisi, ejaan salah, perbaikan sedikit)&nbsp;</div>\r\n<div>\r\n	- tidak ada insheet (lebihan)</div>\r\n<div>\r\n	- tidak disetting hanya tata saja</div>\r\n<div>\r\n	- potong cutter</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	UKURAN MAKSIMAL CETAK = 46.5x31.5</div>\r\n<div>\r\n	bahan 48x32.5</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	JAKARTA&nbsp;</div>\r\n<div>\r\n	PRINT AND CUT :</div>\r\n<div>\r\n	<div>\r\n		harga</div>\r\n	<div>\r\n		&nbsp;vinyl :10.000</div>\r\n	<div>\r\n		Chromo : 3200</div>\r\n	<div>\r\n		&nbsp;</div>\r\n	<div>\r\n		Biaya cutting : 6.000</div>\r\n</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	&nbsp;</div>\r\n', 'pricelist', NULL, NULL, 2, 0, 11),
(241, 'Motor sanggar hurip', '<p>\r\n	1. Motor sanggar dipergunakan untuk membawa barang dari sanggar ke kantor dan sebaliknya<br />\r\n	&nbsp; &nbsp; A. membawa barang dari sanggar ke kantor yang sudah jadi&nbsp;<br />\r\n	&nbsp; &nbsp; &nbsp; &nbsp; a. barang yang bisa diangkut satu kali<br />\r\n	&nbsp; &nbsp; &nbsp; &nbsp; b. barang yang diambil di kantor oleh klien<br />\r\n	&nbsp; &nbsp; &nbsp; &nbsp; c. barang yang dikirim akan tetapi bisa di bawa sekali angkut<br />\r\n	&nbsp; &nbsp; B. mengambil barang dikantor dengan cara bergilir<br />\r\n	&nbsp; &nbsp; &nbsp; &nbsp; a. mengambil cetakan yang mau di finishing dari kantor<br />\r\n	&nbsp; &nbsp; &nbsp; &nbsp; b. mengambil keperluan finishing buat sanggar ( rafia, cutter, lakban, dus, dlsb)<br />\r\n	&nbsp; &nbsp; &nbsp; &nbsp; c. membawa barang secukupnya dimotor (barang yang urgent)<br />\r\n	&nbsp; &nbsp; C. barang diambil setelah habis mengaji / meeting<br />\r\n	&nbsp; &nbsp; D. hari pengambilan barang dari hari senin-kamis untuk meminimalis waktu di hari jumat dan sabtu tdk ada pengambilan.</p>\r\n<p>\r\n	2. Motor sanggar dipergunakan untuk mengambil dan membagi kerjaan di ibu-ibu<br />\r\n	3. motor sanggar tanggung jawab penuh rekan-rekan sanggar hurip.</p>\r\n', 'pengiriman', NULL, NULL, 2, 0, 9),
(242, 'Fotocopy Bandung', '<div>\r\n	update 9 oktober 2017</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	<div>\r\n		ukuran <strong>B5 </strong>hvs 80 gr</div>\r\n	<div>\r\n		1 muka = 170</div>\r\n	<div>\r\n		2 muka = 280</div>\r\n	<div>\r\n		&nbsp;</div>\r\n</div>\r\n<div>\r\n	Fotocopy <strong>A4 </strong>80 gr</div>\r\n<div>\r\n	1 muka = 180</div>\r\n<div>\r\n	2 muka = 300</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	ukuran <strong>Folio </strong>80 gr</div>\r\n<div>\r\n	1 muka = 190</div>\r\n<div>\r\n	2 muka = 330</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	ini harga pokok dari Fotocopy</div>\r\n<body id=\"cke_pastebin\" style=\"position: absolute; top: 36px; width: 1px; height: 1px; overflow: hidden; left: -1000px;\">\r\n	<div>\r\n		ukuran B5 hvs 80 gr</div>\r\n	<div>\r\n		1 muka = 170</div>\r\n	<div>\r\n		2 muka = 280</div>\r\n</body>\r\n', 'pricelist', NULL, NULL, 2, 0, 11),
(243, 'Estimasi Ongkir + Berat Barang', '<p>\r\n	<span style=\"font-size:12px;\">1. Via 4848&nbsp;</span></p>\r\n<p>\r\n	<span style=\"font-size:12px;\">- Tasik / Ciawi / garut = 1 kg pertama Rp 60.000,- selanjutnya 5.000,-</span></p>\r\n<div>\r\n	GARUT:</div>\r\n<div>\r\n	5 kg pertama Rp 60.000</div>\r\n<div>\r\n	1 kg selanjutnya Rp 5.000,-</div>\r\n<div>\r\n	garut kota diantar sampai alamat</div>\r\n<div>\r\n	diluar kota garut diambil di pool garut ( jl cimanuk depan gedung hikmah)</div>\r\n<p>\r\n	<span style=\"font-size:12px;\">2. Herona&nbsp;</span></p>\r\n<p>\r\n	<span style=\"font-size:12px;\">- Cirebon&nbsp;</span>10 kg pertama 60rb&nbsp;</p>\r\n<p>\r\n	<span style=\"font-size: 12px;\">Selanjut nya 2500&nbsp;</span></p>\r\n<div>\r\n	- Surabaya 10 kg pertama 80rb</div>\r\n<div>\r\n	&nbsp; selanjutnya 4500</div>\r\n<p>\r\n	&nbsp;</p>\r\n<p>\r\n	3. Bandung Express</p>\r\n<p>\r\n	<span style=\"font-size:12px;\">- Surabaya =&nbsp;5kg pertama 45.000 selanjutnya 1500 per kg (2-3 hari)</span></p>\r\n<p>\r\n	<span style=\"font-size:12px;\">- Denpasar = 5 kg pertama 55.000 selanjutnya 3.300 per kg</span><span style=\"font-size: 12px;\">&nbsp;</span></p>\r\n<p>\r\n	&nbsp;</p>\r\n<p>\r\n	4. Indah Cargo</p>\r\n<p>\r\n	<span style=\"font-size:12px;\">- Tangerang Kota = Rp 4.500 minimal 11 kg</span></p>\r\n<p>\r\n	<span style=\"font-size: 12px;\">- Cianjur = Rp 6.500 minimal 11 kg</span></p>\r\n<p>\r\n	<span style=\"font-size: 12px;\">- Sumedang = Rp 5.000 per kg</span></p>\r\n<p>\r\n	<span style=\"font-size: 12px;\">- Karawang = Rp 4.500 per kg minimal 11 kg</span></p>\r\n<p>\r\n	<span style=\"font-size: 12px;\">- GARUT :&nbsp;</span>1 kg Rp 5.000,- min 11 kg, waktu kirim 2-3 hari untuk garut kota, pinggiran garut nambah 1 hari</p>\r\n<p>\r\n	5. Garuda Indonesia</p>\r\n<p>\r\n	cek resi di&nbsp;http://icms.garuda-indonesia.com/</p>\r\n<p>\r\n	&nbsp;</p>\r\n<p>\r\n	<strong style=\"font-size: 14px;\">Perhitungan Berat Thumbler Volumetrik</strong></p>\r\n<p>\r\n	<span style=\"font-size:12px;\"><span style=\"font-family:arial,helvetica,sans-serif;\">-&nbsp; 1 thumbler real berat 150 gr, volumetrik 275 gr<br />\r\n	- Jika 1 dus isi 24 pcs = real 3,8 kg ; Volumetriknya 6,6 kg (bulatkan 7 kg)<br />\r\n	- Jika 2 dus disatukan jadi 13 kg</span></span></p>\r\n<p>\r\n	&nbsp;</p>\r\n<p>\r\n	<span style=\"font-size:14px;\"><strong>Perhitungan Berat Ballpoint</strong></span></p>\r\n<p>\r\n	<span style=\"font-size:12px;\"><span style=\"font-family:arial,helvetica,sans-serif;\">- Berat ballpoint Boss 1,3 gram , 50 pcs = 0,572 kg<br />\r\n	- Berat ballpoint Cabe 0,01 gram</span></span></p>\r\n<p>\r\n	&nbsp;</p>\r\n<p>\r\n	<span style=\"font-size:14px;\"><strong>Perhitungan Berat dan Volume Metrik Roll Banner Uk. 60 x 160 cm</strong></span></p>\r\n<p>\r\n	<span style=\"font-size:12px;\"><span style=\"font-family:arial,helvetica,sans-serif;\">- Berat = 1.82 kg<br />\r\n	- P x L x T = 8 x 10 x 60 cm<br />\r\n	- Hitung volume metrik = (P x L x T) / 6000</span></span></p>\r\n<p>\r\n	&nbsp;</p>\r\n<p>\r\n	<strong style=\"font-size: 14px;\">Perhitungan Mug</strong></p>\r\n<p style=\"font-size: 12px;\">\r\n	<span style=\"font-size: 12px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">- 1 pcs Mug = 439 gr</span></span></p>\r\n<p style=\"font-size: 12px;\">\r\n	&nbsp;</p>\r\n<p style=\"font-size: 12px;\">\r\n	TUJUAN CIANJUR</p>\r\n<p style=\"font-size: 12px;\">\r\n	<span style=\"font-family: arial, helvetica, sans-serif;\">BUS MGI flat 1 dus 50rb</span></p>\r\n<p style=\"font-size: 12px;\">\r\n	<span style=\"font-family: arial, helvetica, sans-serif;\">bhinneka travel buah batu Kontak call center 022 522 9568</span></p>\r\n<p style=\"font-size: 12px;\">\r\n	jam keberangkatan :</p>\r\n<div>\r\n	05,&nbsp;</div>\r\n<div>\r\n	07,&nbsp;</div>\r\n<div>\r\n	09,&nbsp;</div>\r\n<div>\r\n	13,&nbsp;</div>\r\n<div>\r\n	14,</div>\r\n<div>\r\n	17.30</div>\r\n<div>\r\n	18.30</div>\r\n<div>\r\n	harga 1 kg pertama 35rb, selanjutnya 10.000</div>\r\n', 'pricelist', NULL, NULL, 2, 0, 11),
(244, 'cetak Express', '<div>\r\n	LAYANAN CETAK EKSPRESS</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	1. wahid ekspres adalah layanan cetak yang bisa beres dalam waktu 3 - 8 jam kerja</div>\r\n<div>\r\n	2. isnain ekspres adalah layanan cetak yang bisa beres dalam waktu 24 jam&nbsp;</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	A. wahid ekspres</div>\r\n<div>\r\n	&nbsp; &nbsp;1. poster atau brosur&nbsp;</div>\r\n<div>\r\n	&nbsp; &nbsp; kriteria :&nbsp;</div>\r\n<div>\r\n	&nbsp; &nbsp; - jumlah order 1 - 500 pcs</div>\r\n<div>\r\n	&nbsp; &nbsp; - Ukuran brosur (a6,a5 &amp; a4), poster (a3 &amp; a3+)</div>\r\n<div>\r\n	&nbsp; &nbsp; - print 1 muka / 2 muka</div>\r\n<div>\r\n	&nbsp; &nbsp; - tanpa laminasi&nbsp;</div>\r\n<div>\r\n	&nbsp; &nbsp; - tanpa lipat</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	&nbsp; &nbsp;2. kartu nama&nbsp;</div>\r\n<div>\r\n	&nbsp; &nbsp; &nbsp;kriteria :&nbsp;</div>\r\n<div>\r\n	&nbsp; &nbsp; - jumlah order 1 - 5 box</div>\r\n<div>\r\n	&nbsp; &nbsp; - ukuran standar kartu nama</div>\r\n<div>\r\n	&nbsp; &nbsp; - print 1 muka / 2 muka</div>\r\n<div>\r\n	&nbsp; &nbsp; - laminasi doff / glossy</div>\r\n<div>\r\n	&nbsp; &nbsp; - potong kotak</div>\r\n<div>\r\n	&nbsp; &nbsp; - laminasi + Rp 5.000, tanpa laminasi + Rp 3.000</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	&nbsp; &nbsp;3. print lembaran (cover buku, dummy lembaran, poster tanpa potong)</div>\r\n<div>\r\n	&nbsp; &nbsp; &nbsp;kriteria :&nbsp;</div>\r\n<div>\r\n	&nbsp; &nbsp; - jumlah order 1 - 500 pcs</div>\r\n<div>\r\n	&nbsp; &nbsp; - Ukuran maks A3+</div>\r\n<div>\r\n	&nbsp; &nbsp; - print 1 muka / 2 muka</div>\r\n<div>\r\n	&nbsp; &nbsp; - tanpa laminasi&nbsp;</div>\r\n<div>\r\n	&nbsp; &nbsp; - tanpa finishing</div>\r\n<div>\r\n	&nbsp; &nbsp;</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	B. isnain ekspres</div>\r\n<div>\r\n	&nbsp; 1.poster atau brosur&nbsp;</div>\r\n<div>\r\n	&nbsp; &nbsp; kriteria :&nbsp;</div>\r\n<div>\r\n	&nbsp; &nbsp; - jumlah order 501 - 1000 pcs</div>\r\n<div>\r\n	&nbsp; &nbsp; - Ukuran brosur (a6,a5 &amp; a4), poster (a3 &amp; a3+)</div>\r\n<div>\r\n	&nbsp; &nbsp; - print 1 muka / 2 muka</div>\r\n<div>\r\n	&nbsp; &nbsp; - laminasi doff/glossy/uv&nbsp;</div>\r\n<div>\r\n	&nbsp; &nbsp; - tanpa lipat</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	&nbsp; 2. kartu nama</div>\r\n<div>\r\n	&nbsp; &nbsp; kriteria :&nbsp;</div>\r\n<div>\r\n	&nbsp; &nbsp; - jumlah order 6 - 20 box</div>\r\n<div>\r\n	&nbsp; &nbsp; - ukuran standar kartu nama</div>\r\n<div>\r\n	&nbsp; &nbsp; - print 1 muka / 2 muka</div>\r\n<div>\r\n	&nbsp; &nbsp; - laminasi doff / glossy</div>\r\n<div>\r\n	&nbsp; &nbsp; - potong kotak&nbsp;</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	&nbsp; 3. buku</div>\r\n<div>\r\n	&nbsp; &nbsp; kriteria :&nbsp;</div>\r\n<div>\r\n	&nbsp; &nbsp; - jumlah order 1 - 20 pcs</div>\r\n<div>\r\n	&nbsp; &nbsp; - ukuran maks A4 postrait (jilid ring bisa A4 Landscape)</div>\r\n<div>\r\n	&nbsp; &nbsp; - cover : kertas AP 260 gr (maks), laminasi doff/glossy</div>\r\n<div>\r\n	&nbsp; &nbsp; - isi buku : maks 40 hal, kertas hvs 100 gr, ap/mp 120-150 gr</div>\r\n<div>\r\n	&nbsp; &nbsp; - finishing : bloklem / ring / hekter</div>\r\n<div>\r\n	&nbsp; &nbsp; - tanpa punggung buku</div>\r\n<div>\r\n	&nbsp; &nbsp; - semua halaman ada list putih (lebar list putih 0,&nbsp; &nbsp;mm)</div>\r\n<div>\r\n	&nbsp; &nbsp; - setting tidak dikasih lebihan</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	&nbsp; 4. notes&nbsp;</div>\r\n<div>\r\n	&nbsp; &nbsp; &nbsp;kriteria :&nbsp;</div>\r\n<div>\r\n	&nbsp; &nbsp; - jumlah order 1 - 30 pcs</div>\r\n<div>\r\n	&nbsp; &nbsp; - ukuran maks A4</div>\r\n<div>\r\n	&nbsp; &nbsp; - cover : kertas AP 260 gr (maks), laminasi doff/glossy</div>\r\n<div>\r\n	&nbsp; &nbsp; - isi buku : maks 50 lembar, kertas hvs 100 gr, ap/mp 120-150 gr, print 1 muka</div>\r\n<div>\r\n	&nbsp; &nbsp; - finishing : bloklem / ring&nbsp;</div>\r\n<div>\r\n	&nbsp; &nbsp; - harga lebih murah : isi pake fotocopy</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	KETENTUAN UMUM ORDER&nbsp;</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	&nbsp; 1. proses menggunakan mesin digital print (jasa print bandung)</div>\r\n<div>\r\n	&nbsp; 2. pembayaran cetak dilakukan di awal (lunas)</div>\r\n<div>\r\n	&nbsp; 3. file siap cetak</div>\r\n<div>\r\n	&nbsp; &nbsp; &nbsp;- tidak ada edit file</div>\r\n<div>\r\n	&nbsp; &nbsp; &nbsp;- tidak ada revisi file</div>\r\n<div>\r\n	&nbsp; &nbsp; &nbsp;- tidak ada konfirmasi file</div>\r\n<div>\r\n	&nbsp; &nbsp; &nbsp;- file sudah di curve ( tidak missing font )</div>\r\n<div>\r\n	&nbsp; 4. kesalahan cetak di luar tanggung jawab percetakan bandung</div>\r\n<div>\r\n	&nbsp;&nbsp;</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	MARKETING&nbsp;</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	&nbsp; - menawarkan order ekspres</div>\r\n<div>\r\n	&nbsp; - memaximalkan menggunakan mesin konica</div>\r\n<div>\r\n	&nbsp; - menggunakn harga konika yang sudah di gunakan</div>\r\n<div>\r\n	&nbsp; - Order diutamakan, brosur (a6,a5 &amp; a4), poster (a3 &amp; a3+) bisa di tunggu</div>\r\n<div>\r\n	&nbsp; - kartunama</div>\r\n<div>\r\n	&nbsp; - order sekala kecil akan tetapi ada finishing</div>\r\n<div>\r\n	&nbsp; - file start masuk terhitung waktu</div>\r\n<div>\r\n	&nbsp; - file di folder seperti biasa</div>\r\n<div>\r\n	&nbsp; - marketing langsung konfrim ke&nbsp; PJ bahwa ada order ekspres A,B/C</div>\r\n<div>\r\n	&nbsp; - Barang diambil / pake jasa pengiriman (gojek/grab - biaya ditanggung konsumen)</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	&nbsp;PJ CETAK EKSPRESS</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	&nbsp; - cek kerjaan ekspress di project (tanda di project : ZKI)&nbsp;</div>\r\n<div>\r\n	&nbsp; &nbsp; (jika sedang setting order standar, maka itu ditunda dl...koordinasi sama spv setting)</div>\r\n<div>\r\n	&nbsp; - baca spek kerjaan</div>\r\n<div>\r\n	&nbsp; - langsung proses sesuai order yang diminta</div>\r\n<div>\r\n	&nbsp; - koordinasi dengan bagian marketing n produksi</div>\r\n<div>\r\n	&nbsp; - jika order sudah beres langsung konfirmasi ke bagian marketing</div>\r\n', 'marketing', NULL, NULL, 2, 0, 4),
(245, 'Pisau', '<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	<strong>MEKANISME PENYIMPANAN PISAU POND</strong></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	<strong>Pisau Awal</strong></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	1. Kelompokkan pisau pond sesuai kode ( P / BR / H / L dll)</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	2. Posisi pisau masih ada di 2 rak yg dipake sekarang (rak deket mesin potong n mesin pond)</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	3. Rentang waktu penyortiran pisau untuk tahap awal ini mulai dari bulan MEI &ndash; DESEMBER 2018</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	&nbsp;</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	<strong>Pisau Sortir</strong></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	1. Pisau sortir adalah pisau awal yg dipake kembali dalam rentang waktu penyortiran diatas</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	2. Rak yg digunakan untuk menyimpan pisau sortir adalah rak yg dekat meja finishing</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	3. Pisau Awal setelah di gunakan untuk ngepond dalam rentang waktu diatas maka pisau tersebut tidak disimpan lagi di rak awal tetapi disimpan di rak sortiran.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	4. Pisau baru yg dibuat dalam rentang waktu penyoritan diatas maka langsung disimpan di rak penyortiran.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	5. Pisau pond yang tidak berpindah tempat ke rak penyortiran selama rentang waktu penyortiran diatas maka pisau pond tersebut akan dibuang.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	6. Mekanisme pembuangan pisaunya silahkan koordinasi dengan UDIN</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	7. Data pisau-pisau pond yang ada di rak penyortiran, kemudian laporkan datanya ke kembar (UDIN) untuk sinkronisasi data pisau di project.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	&nbsp;</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	<strong>CATATAN : DIBUTUHKAN KOMITMEN N KONSISTENSI UNTUK MEMASTIKAN MENYIMPAN PISAU SORTIR DI RAK PENYORTIRAN....</strong></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	<strong>Data Pisau Pond di Server</strong></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	1. buat 2 folder data a. Pisau Baru b. Pisau Lama</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	2. data2 pisau lama yang dibuat sebelum aturan ini dibuat maka datanya disimpan/pindahkan di folder pisau lama</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	3. pisau baru yg dibuat setelah aturan ini dibuat makan disimpan di folder pisau baru</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	4. sinkronisasi data pisau lama yg disortir - pisau lama yg statusnya hasil sortir maka data pisaunya dipindahkan ke folder pisau baru</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	5. pisau lama yg statusya pisau dibuang maka datanya jangan dihapus, tetap dibiarkan ada di folder pisau lama</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	6. penomoran pisau tetep terus dilanjutkan, tidak perlu mengisi lagi nomor2 awal sebagai pengganti pisau yg dibuang</p>\r\n', 'setting', NULL, NULL, 2, 0, 3),
(247, 'Pisau', '<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	<strong>MEKANISME PENYIMPANAN PISAU POND</strong></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	<strong>Pisau Awal</strong></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	1. Kelompokkan pisau pond sesuai kode ( P / BR / H / L dll)</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	2. Posisi pisau masih ada di 2 rak yg dipake sekarang (rak deket mesin potong n mesin pond)</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	3. Rentang waktu penyortiran pisau untuk tahap awal ini mulai dari bulan MEI &ndash; DESEMBER 2018</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	&nbsp;</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	<strong>Pisau Sortir</strong></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	1. Pisau sortir adalah pisau awal yg dipake kembali dalam rentang waktu penyortiran diatas</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	2. Rak yg digunakan untuk menyimpan pisau sortir adalah rak yg dekat meja finishing</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	3. Pisau Awal setelah di gunakan untuk ngepond dalam rentang waktu diatas maka pisau tersebut tidak disimpan lagi di rak awal tetapi disimpan di rak sortiran.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	4. Pisau baru yg dibuat dalam rentang waktu penyoritan diatas maka langsung disimpan di rak penyortiran.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	5. Pisau pond yang tidak berpindah tempat ke rak penyortiran selama rentang waktu penyortiran diatas maka pisau pond tersebut akan dibuang.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	6. Mekanisme pembuangan pisaunya silahkan koordinasi dengan UDIN</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	7. Data pisau-pisau pond yang ada di rak penyortiran, kemudian laporkan datanya ke kembar (UDIN) untuk sinkronisasi data pisau di project.</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	&nbsp;</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	<strong>CATATAN : DIBUTUHKAN KOMITMEN N KONSISTENSI UNTUK MEMASTIKAN MENYIMPAN PISAU SORTIR DI RAK PENYORTIRAN....</strong></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	<strong>Data Pisau Pond di Server</strong></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	1. buat 2 folder data a. Pisau Baru b. Pisau Lama</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	2. data2 pisau lama yang dibuat sebelum aturan ini dibuat maka datanya disimpan/pindahkan di folder pisau lama</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	3. pisau baru yg dibuat setelah aturan ini dibuat makan disimpan di folder pisau baru</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	4. sinkronisasi data pisau lama yg disortir - pisau lama yg statusnya hasil sortir maka data pisaunya dipindahkan ke folder pisau baru</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	5. pisau lama yg statusya pisau dibuang maka datanya jangan dihapus, tetap dibiarkan ada di folder pisau lama</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">\r\n	6. penomoran pisau tetep terus dilanjutkan, tidak perlu mengisi lagi nomor2 awal sebagai pengganti pisau yg dibuang</p>\r\n', 'finishing', NULL, NULL, 2, 0, 12);
