INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(249, 'pengetahuan umum', '<p>\r\n	mika roll ukuran 140 x 50 meter = 875 rb, pelurusan 300 rb ukuran 0.30 putih, pelurusan sudah termasuk potong</p>\r\n<p>\r\n	mika roll ukuran 70x100 meter = 2jt, pelurusan 300rb, &nbsp;tebal 0.50 putih</p>\r\n<p>\r\n	22/08 2016 toko uninon&nbsp;</p>\r\n<p>\r\n	mika ukuran 54x74 cm</p>\r\n<p>\r\n	burem 25rb</p>\r\n<p>\r\n	putih 35rb</p>\r\n<p>\r\n	potong 5 rb</p>\r\n<p>\r\n	waktu potong 2 hari&nbsp;</p>\r\n<p>\r\n	&nbsp;</p>\r\n<p>\r\n	laser di polar:</p>\r\n<p>\r\n	- bisa kertas laminasi baik itu doff atau glossy</p>\r\n<p>\r\n	- ada efek terbakarnya di sekeliling nya yang dilaser</p>\r\n<p>\r\n	- harganya : softcover 30/cm/vector, hardcover 50/cm/vector</p>\r\n<p>\r\n	&nbsp;</p>\r\n<p>\r\n	print albatros = &nbsp;maksimal lebar 1,4 meter, panjang maksimal 5 meter</p>\r\n<p>\r\n	<span style=\"color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">uk karton 64x75, ukuran kain linen 120x1600 cm, ukuran albatro jkt maksimal 1,4 meter lebarnya</span></p>\r\n<p>\r\n	<span style=\"color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">amplop coklat 24x11 = 17rb. 35x24=38rb, 39x29=55rb semua isi 100pcs tanya di toko budhi</span></p>\r\n<p>\r\n	<span style=\"color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">harga dudkan 17x24 cm 6500, kalau A5 4500</span></p>\r\n<p>\r\n	<span style=\"color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">reset EDC tekan fucntion lalu angka 3 lalu tekan enter (hijau) lalu password 3636 lalu enter, kartu didalam mesin dipakai indosat MAtrix (abodemen) jadi klien tinggal pakai saja, untuk test koneksi : tekan F tekan O lalu enter</span></p>\r\n<p>\r\n	<span style=\"color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">berat ballpoint boss 1,3 gram</span></p>\r\n<p>\r\n	starlite book paper 55 gr = &nbsp;1300/satuan = 385.000,-/rim ukuran plano 63.5 x 88 cm</p>\r\n<p>\r\n	<span style=\"color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">starlite book paper 70 gr = &nbsp;539.000,-/rim ukuran plano 63.5 x 88 cm</span></p>\r\n<p>\r\n	harga banner&nbsp;<strong>per meter:</strong></p>\r\n<p>\r\n	<strong>POLA (NIKEN) :</strong></p>\r\n<p>\r\n	<strong>260 gr = 13.000</strong></p>\r\n<p>\r\n	<strong>280 gr = 15.000</strong></p>\r\n<p>\r\n	<strong>440 gr = 50.000</strong></p>\r\n<p>\r\n	&nbsp;</p>\r\n<p>\r\n	<strong>POLAR (ASIH) :</strong></p>\r\n<p>\r\n	<strong>280 gr = 15.000&nbsp;</strong></p>\r\n<p>\r\n	<strong>300 gr</strong><strong>&nbsp;= 30.000</strong></p>\r\n<p>\r\n	<strong>340 gr</strong><strong>&nbsp;= 35.000</strong></p>\r\n<p>\r\n	<strong>380 gr</strong><strong>&nbsp;= 40.000</strong></p>\r\n<p>\r\n	<strong>440 gr</strong><strong>&nbsp;= 50.000</strong></p>\r\n<p>\r\n	Mesin Banner flexi pola, polar dan zentech semuanya lebar 3 meter lebih dari itu disambung</p>\r\n<p>\r\n	zentech flexi korea yg 5 meter</p>\r\n<p>\r\n	<strong>sapta jaya</strong></p>\r\n<p>\r\n	book paper tipis 60 gr 270rb/rim plano 61x86</p>\r\n<p>\r\n	&nbsp;</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	stiker transparant</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	pola per A3 20rb jual 40rb</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	&nbsp;</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	harga cutting stiker : Rp 75 cm / warna</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	&nbsp;</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	Central SPS 28 juli 2016</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	tiang x banner standar beli 11.000 bahan plastik</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	yang bagus bahan fiber 23.000/pcs bahan fiber putih</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	&nbsp;</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	Flexi cina HIRES JAKARTA</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	18500/meter , ketebalan 340 gr</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	16.500/meter, ketbalan 280 gr</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	&nbsp;</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	<strong>finishing:</strong></p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	kalding seng&nbsp;</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	hekter per lembar 50</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	seng 60</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	urutin 15 per lembar&nbsp;</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	&nbsp;</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	Zentech (19 -09-2016)</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	print and cut Ukuran A3&nbsp;</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	bahan Vinyl laminasi doff atau glossy = 30.000,-</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	bahan Vinyl tanpa laminasi = 27.500,-</p>\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; padding: 0px; color: rgb(85, 85, 85); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; line-height: 20px;\">\r\n	bahan chromo tanpa laminasi &nbsp;= 22.500,-</p>\r\n<p>\r\n	flexi korea 90rb per meter (dari zentechnya 65.000), ga bisa ukuran kecil harus besar2)</p>\r\n<p>\r\n	flexi Jerman 125rb per meternya (HPP 100.000,-)</p>\r\n<p>\r\n	bahan 11OZ 65rb per meternya (HPP 40.000,-)</p>\r\n<p>\r\n	flexi cina 300 gr 35rb (HPP 20rb)</p>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	Fajar jkt 26 sep 2016</div>\r\n<div>\r\n	bahan indigo :</div>\r\n<div>\r\n	Kalo kromo merk fastek, klo vynil duratax pak</div>\r\n<div>\r\n	cetak :</div>\r\n<div>\r\n	fastek vinyl dan chromo</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	12 okt 2016</div>\r\n<div>\r\n	1 rol kain linen</div>\r\n<div>\r\n	ukuran 120 cm x 6 meter</div>\r\n<div>\r\n	dapat 93 pcs komplit dudukan kalender ukuran A5</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	STEMPEL POLA</div>\r\n<div>\r\n	bentuk kotak bebas ukuran&nbsp;</div>\r\n<div>\r\n	minimal 2 mm jarak per warna</div>\r\n<div>\r\n	paling besar 8x4 cm 85 rb, 1 warna</div>\r\n<div>\r\n	untuk yang bulat ada ketentuan ukurannya</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	setting kartu nama offset maksimal 28 nama</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	stiker transparant&nbsp;</div>\r\n<div>\r\n	indigo jakarta =&nbsp;</div>\r\n<div>\r\n	1-300 = 12.000</div>\r\n<div>\r\n	301-500 = 11.000</div>\r\n<div>\r\n	501-1000 = 10.000</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	finishing buku :</div>\r\n<div>\r\n	lipat = lipat, ngurut, blok lem</div>\r\n<div>\r\n	cacah = potong, ngurut, blok lem</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	lipat 2 di A3 = 1000 lbr 85rb selanjutnya 15/lembar --&gt; untuk buku ukuran A5</div>\r\n<div>\r\n	ngurutin 15/lembar</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	cacah = 700/kg</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	blok lem = pxtebalx30 , min 350rb</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	<span style=\"color: rgb(75, 75, 75); font-family: Roboto, sans-serif; font-size: 16px; white-space: pre-wrap;\">Just info Harga Agenda: (pak apep 9 oktober 2017) </span></div>\r\n<div>\r\n	<span style=\"color: rgb(75, 75, 75); font-family: Roboto, sans-serif; font-size: 16px; white-space: pre-wrap;\">uk A5 kulit *ASLI* bukan imitasi foil </span></div>\r\n<div>\r\n	<span style=\"color: rgb(75, 75, 75); font-family: Roboto, sans-serif; font-size: 16px; white-space: pre-wrap;\">harga Rp 250.000,- /pcsnya </span></div>\r\n<div>\r\n	<span style=\"color: rgb(75, 75, 75); font-family: Roboto, sans-serif; font-size: 16px; white-space: pre-wrap;\">- harga kulit mahal </span></div>\r\n<div>\r\n	<span style=\"color: rgb(75, 75, 75); font-family: Roboto, sans-serif; font-size: 16px; white-space: pre-wrap;\">- ongkos jahitnya lebih mahal dari yang biasa </span></div>\r\n<div>\r\n	<span style=\"color: rgb(75, 75, 75); font-family: Roboto, sans-serif; font-size: 16px; white-space: pre-wrap;\">- harga belum termasuk isi agenda</span></div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	<span style=\"color: rgb(75, 75, 75); font-family: Roboto, sans-serif; font-size: 16px; white-space: pre-wrap;\">Stiker Transparant (meteran) maksimal 1.5 m :</span></div>\r\n<div>\r\n	<span style=\"color: rgb(75, 75, 75); font-family: Roboto, sans-serif; font-size: 16px; white-space: pre-wrap;\">ukuran 1 x 1 m = Rp 150.000 (sudah harga jual)</span></div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	<span style=\"color: rgb(75, 75, 75); font-family: Roboto, sans-serif; font-size: 16px; white-space: pre-wrap;\">POLAR SPS punkur</span></div>\r\n<div>\r\n	<span style=\"color: rgb(75, 75, 75); font-family: Roboto, sans-serif; font-size: 16px; white-space: pre-wrap;\">print A0 bahan AP 260 gr HPP 125.000,-</span></div>\r\n<div>\r\n	<span style=\"color: rgb(75, 75, 75); font-family: Roboto, sans-serif; font-size: 16px; white-space: pre-wrap;\">laminasi 50rb jadi total 175.000,-</span></div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	<span style=\"color: rgb(75, 75, 75); font-family: Roboto, sans-serif; font-size: 16px; white-space: pre-wrap;\">Finishing thumbler = 300</span></div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	POLAR</div>\r\n<div>\r\n	print kaos&nbsp;</div>\r\n<div>\r\n	bahan dari sana 125.000,-</div>\r\n<div>\r\n	bahan kaos Kenari</div>\r\n<div>\r\n	sehari jadi (print 2 jam)</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	POLA :<br />\r\n	Stempel Bulat :<br />\r\n	1. ukuran 2 cm = Rp 60.000/warna<br />\r\n	2. ukuran 4 cm = Rp 73.000/warna<br />\r\n	per warna nambah RP 5.000</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	lipat mesin</div>\r\n<div>\r\n	spek A4 lipat 3 Uv 2 muka</div>\r\n<div>\r\n	1000 pcs pertama 85 selanjutnya 25</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	Print an cut jakarta (uk A3)</div>\r\n<div>\r\n	<div>\r\n		haga</div>\r\n	<div>\r\n		&nbsp;vinyl :10.000</div>\r\n	<div>\r\n		Chromo : 3200</div>\r\n	<div>\r\n		Biaya cutting : 6.000</