(253, 'MESIN PRINTER JET PRESS', '<p>\r\n	<span style=\"font-size:20px;\"><span style=\"color: rgb(85, 85, 85); font-family: \" helvetica=\"\" neue\",=\"\" helvetica,=\"\" arial,=\"\" sans-serif;\"=\"\">Order &lt;= 150 pcs , di print pakai <strong>mesin jet press 75&nbsp;</strong></span></span></p>\r\n<p>\r\n	<span style=\"font-size:20px;\"><span style=\"color: rgb(85, 85, 85); font-family: \" helvetica=\"\" neue\",=\"\" helvetica,=\"\" arial,=\"\" sans-serif;\"=\"\"><strong>Ukuran kecil : </strong><br>\r\n	area cetak maks : <strong>64x47 cm2&nbsp;</strong><br>\r\n	ukuran bahan : <strong>64,8x49,8 cm2</strong><br>\r\n	maksimal print : <strong>2 A3 / 1 A2&nbsp;</strong></span></span></p>\r\n<p>\r\n	<span style=\"font-size:20px;\"><span style=\"color: rgb(85, 85, 85); font-family: \" helvetica=\"\" neue\",=\"\" helvetica,=\"\" arial,=\"\" sans-serif;\"=\"\"><strong>Ukuran Besar : </strong><br>\r\n	area cetak maks : <strong>73x51,5 cm2&nbsp;</strong><br>\r\n	ukuran bahan : <strong>75x54,3 cm2</strong></span></span></p>', 'cetak', NULL, '2025-01-31 22:04:16', 2, 0, 10),
(254, 'tas sekolah', '<p>\r\n	bahan dobly + bordir<br />\r\n	100 - 200 harga 170.000 ( harga jual )<br />\r\n	201 - 300 harga 165.000 ( harga jual )<br />\r\n	301 - 500 harga 160.000 ( harga jual</p>\r\n', 'pricelist', NULL, NULL, 2, 0, 11),
(255, 'kardus box', '<p>\r\n	bahan corrugated</p>\r\n<p>\r\n	ukuran plano dus 80x115<br />\r\n	area maximal pond 50x70&nbsp;</p>\r\n<p>\r\n	harga Rp 9.000 per plano</p>\r\n', 'pricelist', NULL, NULL, 2, 0, 11),
(256, 'Kardus Coklat (Polosan)', '<p>\r\n	- Dus polosan</p>\r\n<p>\r\n	- Bisa sablon 1-2 warna, tinggal ditambah harga sablon</p>\r\n<p>\r\n	- Ukuran dibawah ini ready stok, tidak ada minimal order</p>\r\n<p>\r\n	- Ukuran custom, PO 2 bulan</p>\r\n<p>\r\n	<img alt=\"\" src=\"data:image/png;base64,\" /></p>\r\n', 'pricelist', NULL, NULL, 2, 0, 11);
