(270, 'upload toped', '<div>\r\n	input keuangan toped</div>\r\n<div>\r\n	1. klik saldo</div>\r\n<div>\r\n	2. klik semua transaksi</div>\r\n<div>\r\n	3. klik tanggal minim 1 pekan</div>\r\n<div>\r\n	4. downlod riwayat</div>\r\n<div>\r\n	5. buka dengan libre</div>\r\n<div>\r\n	6. save ke exel 97-2003</div>\r\n<div>\r\n	7. upload ke project</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	input order lazada</div>\r\n<div>\r\n	1. klik pesanan</div>\r\n<div>\r\n	2. klik semua pesanan</div>\r\n<div>\r\n	3. atur rentang tanggal minim 1 pekan</div>\r\n<div>\r\n	4. klik download laporan penjualan</div>\r\n<div>\r\n	5. buka dengan libre</div>\r\n<div>\r\n	6. save ke exel 97-2003</div>\r\n<div>\r\n	7. upload ke project</div>\r\n', 'order', NULL, NULL, 2, 0, 6),
(271, 'upload lazada', '<div>\r\n	order</div>\r\n<div>\r\n	1.pesanan</div>\r\n<div>\r\n	2. klik versi lama</div>\r\n<div>\r\n	3. klik semua</div>\r\n<div>\r\n	4. klik rentang tanggal</div>\r\n<div>\r\n	5. klik ok lalu cari</div>\r\n<div>\r\n	6. klik ekspor pencarian pesanan</div>\r\n<div>\r\n	7. klik lihat riwayat ekspor</div>\r\n<div>\r\n	8. klik download paling atas ( Download Result File )</div>\r\n<div>\r\n	9. buka menggunakan libre</div>\r\n<div>\r\n	10. save ke EXEL 97-2003</div>\r\n<div>\r\n	11. upload ke project</div>\r\n<div>\r\n	&nbsp;</div>\r\n<div>\r\n	keuangan</div>\r\n<div>\r\n	1. klik saldo toko</div>\r\n<div>\r\n	2. klik semua</div>\r\n<div>\r\n	3. klik rentang tanggal</div>\r\n<div>\r\n	4. klik ok</div>\r\n<div>\r\n	5. unduh detail transaksi ( csv )</div>\r\n<div>\r\n	6. langsung upload project</div>\r\n<div>\r\n	&nbsp;</div>\r\n', 'order', NULL, NULL, 2, 0, 6),
(272, 'asdf', '<p>asfd</p>', 'pengiriman', '2025-01-31 22:36:37', '2025-01-31 22:36:37', 18, NULL, NULL),
(275, 'CUTTINGAN', '<p><span style=\"font-weight: bolder;\">SEMUA CUTTINGAN DI JASA PRINT HARUS SELESAI 1 HARI BERES, KECUALI CUTTINGAN YANG MASUK DI JAM 5 SORE BOLEH DI JADWALKAN BESOK HARINYA.<br></span><img src=\"file:///C:/Users/erwinpbservice/Downloads/WhatsApp%20Image%202025-03-05%20at%2009.51.04_1dd496ed%20(1).png\" alt=\"\"><img src=\"file:///C:/Users/erwinpbservice/Downloads/WhatsApp%20Image%202025-03-05%20at%2009.51.04_1dd496ed%20(1).png\" style=\"font-size: 1rem;\" alt=\"\"><span style=\"font-weight: bolder;\"></span></p>', '', '2025-03-05 17:36:11', '2025-03-05 17:36:11', NULL, NULL, 13),
(276, 'LAMINASIAN', '<p>UNTUK LAMINASIAN, <br>1.JIKA JUMLAHNYA DIATAS 200 LBR BOLEH LAMINASIKAN KELUAR DENGAN SYARAT BAHAN SATU UKURAN&nbsp;<br>2.SETIAP ADA LAMINASIAN DI JADWALKAN 1 HARI (PAGI SIANG DAN SORE), JIKA ADA LAMINASIAN YANG URGENT, WAJIB LANGSUNG DI LAMINASI.<br>3. LAMINASIAN YANG MASUK LEWAT DARI JAM 5, BOLEH DI JADWALKAN KE BESOK HARINYA.</p>', '', '2025-03-05 17:39:33', '2025-03-05 17:39:33', NULL, NULL, 13),
(277, 'PRINTAN', '<p>1. CEK PRINTAN SESUAI DENGAN FILENYA, JIKA ADA MASALAH DARI FILE WAJIB KONFIRMASI KEPADA YANG BERSANGKUTAN BAIK ITU PB,PK,ATAU DSB.<br>2. TES PRINT 1 PCS DULU, DAN ACC KAN KEPADA YANG BERSANGKUTAN.<br>3. PASTIKAN BAHAN SESUAI DENGAN SPEK RENAME, YAITU B5,B4+,A3 MAUPUN A3+.<br>4. PASTIKAN SELALU CEK FILE KETIKA MAU NGE PRINT, ENTAH ITU FULLCOLUR ATAU BLACK WHITE.</p>', '', '2025-03-05 17:45:03', '2025-03-05 17:45:03', NULL, NULL, 13),
(278, 'TATA TERTIB', '<p style=\"box-sizing: inherit; margin-bottom: 1rem; background-color: rgb(233, 237, 242);\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\">TATA TERTIB</font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Mentaati ketentuan waktu kerja</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Seluruh karyawan wajib untuk mengikuti tilawah pagi &amp; briefing pagi</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan yang berada di kantor pada saat jam shalat (dhuhur &amp; ashar) berkewajiban untuk mengikuti shalat berjamaah (khusus ikhwan shalat berjamaah di masjid)</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Tidak boleh mendengarkan musik saat jam kerja.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Tidak boleh menonton youtube, tiktok, dan download pribadi &amp; lainnya, saat jam kerja.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Tidak boleh merokok bagi karyawan &amp; freelance</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Tidak boleh bergadang untuk kepentingan &amp; kesenangan diri sendiri, misal bermain game, dan lainnya</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Dilarang berbuat asusila dilingkungan perusahaan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">dilarang melakukan manipulasi data perusahaan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Tidak diperbolehkan melakukan kegiatan usaha pribadi yang sama dengan jenis bisnis perusahaan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Dilarang melakukan transaksi ribawi</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Setiap hari sabtu diwajibkan sholat dzuhur berjamaah terlebih dahulu sebelum pulang.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Setiap waktu sholat, saat tiba dimesjid harus langsung bergegas untuk masuk kedalam mesjid, tidak boleh duduk atau mengobrol terlebih dahulu diteras mesjid.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Seluruh karyawan berkewajiban untuk menjaga kebersihan dan kerapihan, seperti : area tempat kerjanya, tempat makan dan minum, sandal/sepatu disimpan pada tempatnya, dan parkir kendaraan ditempat yang telah ditentukan.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Melaksanakan tugas/pekerjaan dengan sebaik-baiknya, penuh pengabdian, kesadaran dan bertanggung jawab.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Menjaga &amp; tidak membocorkan rahasia perusahaan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Memelihara dan meningkatkan keutuhan, kekompakan dan persatuan untuk menciptakan suasana kerja yang baik sesuai dengan harapan perusahaan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Menggunakan dan memelihara barang-barang milik perusahaan dengan sebaik-baiknya.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Berpenampilan rapih dan bersih.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">bersikap dan bertingkah laku sopan santun terhadap masyarakat dan sesama karyawan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Bersikap sopan, jujur dan selalu mentaati perintah atasan dalam melakukan pekerjaannya serta selalu meningkatkan efisiensi dan produktifitas kerja</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Tidak melakukan perbuatan yang dapat merusak atau merugikan nama baik perusahaan, pimpinan atau teman sekerja, dan harus memelihara kerjasama yang baik diantara karyawan untuk menciptakan ketenangan kerja dan memelihara ketertiban dalam perusahaan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Menggunakan, menjalankan atau menyimpan dengan baik semua peralatan atau mesin-mesin, bahan-bahan atau surat-surat berharga milik perusahaan yang dipercayakan kepadanya</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Bertanggung jawab atas semua barang atau harta milik perusahaan yang dipercayakan kepadanya dan harus segera melaporkan kehilangan atau kerusakan yang terjadi terhadap barang-barang atau harta milik perusahaan tersebut kepada atasannya.</font></font></p></li></ul>', '', '2025-04-24 17:20:39', '2025-05-05 21:14:04', NULL, NULL, 15);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(279, 'TATA TERTIB', '<p><font face=\"Arial, sans-serif\">TATA TERTIB</font></p><ul><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Mentaati\r\n	ketentuan waktu kerja</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Seluruh\r\n	karyawan wajib untuk mengikuti tilawah pagi &amp; briefing pagi</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Karyawan\r\n	yang berada di kantor pada saat jam shalat (dhuhur &amp; ashar)\r\n	berkewajiban untuk mengikuti shalat berjamaah (khusus ikhwan shalat\r\n	berjamaah di masjid)</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Tidak\r\n	boleh mendengarkan musik saat jam kerja.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Tidak\r\n	boleh menonton youtube, tiktok, dan download pribadi &amp; lainnya,\r\n	saat jam kerja.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Tidak\r\n	boleh merokok bagi karyawan &amp; freelance</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Tidak\r\n	boleh bergadang untuk kepentingan &amp; kesenangan diri sendiri,\r\n	misal bermain game, dan lainnya</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Dilarang\r\n	berbuat asusila dilingkungan perusahaan</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">dilarang\r\n	melakukan manipulasi data perusahaan</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Tidak\r\n	diperbolehkan melakukan kegiatan usaha pribadi yang sama dengan\r\n	jenis bisnis perusahaan</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Dilarang\r\n	melakukan transaksi ribawi</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Setiap\r\n	hari sabtu diwajibkan sholat dzuhur berjamaah terlebih dahulu\r\n	sebelum pulang.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Setiap\r\n	waktu sholat, saat tiba dimesjid harus langsung bergegas untuk masuk\r\n	kedalam mesjid, tidak boleh duduk atau mengobrol terlebih dahulu\r\n	diteras mesjid.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Seluruh\r\n	karyawan berkewajiban untuk menjaga kebersihan dan kerapihan,\r\n	seperti : area tempat kerjanya, tempat makan dan minum,\r\n	sandal/sepatu disimpan pada tempatnya, dan parkir kendaraan ditempat\r\n	yang telah ditentukan.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Melaksanakan\r\n	tugas/pekerjaan dengan sebaik-baiknya, penuh pengabdian, kesadaran\r\n	dan bertanggung jawab.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Menjaga\r\n	&amp; tidak membocorkan rahasia perusahaan</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Memelihara\r\n	dan meningkatkan keutuhan, kekompakan dan persatuan untuk\r\n	menciptakan suasana kerja yang baik sesuai dengan harapan perusahaan</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Menggunakan\r\n	dan memelihara barang-barang milik perusahaan dengan sebaik-baiknya.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Berpenampilan\r\n	rapih dan bersih.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">bersikap\r\n	dan bertingkah laku sopan santun terhadap masyarakat dan sesama\r\n	karyawan</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Bersikap\r\n	sopan, jujur dan selalu mentaati perintah atasan dalam melakukan\r\n	pekerjaannya serta selalu meningkatkan efisiensi dan produktifitas\r\n	kerja</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Tidak\r\n	melakukan perbuatan yang dapat merusak atau merugikan nama baik\r\n	perusahaan, pimpinan atau teman sekerja, dan harus memelihara\r\n	kerjasama yang baik diantara karyawan untuk menciptakan ketenangan\r\n	kerja dan memelihara ketertiban dalam perusahaan</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Menggunakan,\r\n	menjalankan atau menyimpan dengan baik semua peralatan atau\r\n	mesin-mesin, bahan-bahan atau surat-surat berharga milik perusahaan\r\n	yang dipercayakan kepadanya</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Bertanggung\r\n	jawab atas semua barang atau harta milik perusahaan yang\r\n	dipercayakan kepadanya dan harus segera melaporkan kehilangan atau\r\n	kerusakan yang terjadi terhadap barang-barang atau harta milik\r\n	perusahaan tersebut kepada atasannya.</font></font></p>\r\n	\r\n</li></ul>', '', '2025-04-24 20:10:47', '2025-05-05 20:37:31', NULL, NULL, 16);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(280, 'HARI &amp;JAM KERJA', '<p style=\"line-height: 100%; margin-bottom: 0in\">\r\n<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>Hari\r\nKerja</strong></font></font></p><p style=\"line-height: 100%; margin-bottom: 0in;\">\r\n<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Hari\r\nkerja dalam 1 minggu 6 hari (senin – sabtu)</font></font></p><p style=\"line-height: 100%; margin-bottom: 0in;\">\r\n<br>\r\n\r\n</p><p style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>Jam\r\nKerja</strong></font></font></p><p style=\"line-height: 100%; margin-bottom: 0in;\">\r\n<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Senin\r\n– Jum’at : pkl.08.30 – 17.00 WIB</font></font></p><p style=\"line-height: 100%; margin-bottom: 0in;\">\r\n<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Sabtu\r\n: pkl.08.00 – 12.00 WIB</font></font></p><p style=\"line-height: 100%; margin-bottom: 0in;\">\r\n<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Istirahat\r\n1 jam mulai pkl.12.00 – 13.00 WIB</font></font></p><p style=\"line-height: 100%; margin-bottom: 0in;\">\r\n<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Jika\r\nkaryawan masih bekerja diluar waktu kerja yang telah ditentukan dan\r\natas permintaan atasannya langsung, maka kelebihan jam kerja tersebut\r\ndihitung sebagai lembur.</font></font></p><p style=\"line-height: 100%; margin-bottom: 0in;\">\r\n<strong><br>\r\n\r\n</strong></p><p style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>Libur\r\nKerja</strong></font></font></p><p style=\"line-height: 100%; margin-bottom: 0in;\">\r\n<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Hari\r\nahad dan hari libur nasional</font></font></p><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p style=\"line-height: 100%; margin-bottom: 0in;\">\r\n<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Libur\r\nhari raya idul fitri ditentukan kemudian disesuaikan dengan kondisi\r\nyang ada</font></font></p>', '', '2025-04-24 20:13:36', '2025-04-24 20:13:36', NULL, NULL, 17);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(281, 'ABSENSI', '<p style=\"line-height: 100%; margin-bottom: 0in\">\r\n<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>ABSENSI</strong></font></font></p><table class=\"table table-zebra w-full text-base [&amp;_a]:text-blue-600\" style=\"width: 1322.47px; border-spacing: 0px; border-radius: 8px; font-size: medium; line-height: 1.5;\"><tbody><tr class=\"bg-base-200/50\" style=\"background-color: oklab(0.98 0 0 / 0.5);\"><td colspan=\"2\" class=\"py-3\" style=\"padding-block: 12px;\"><p style=\"font-size: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Absensi menggunakan&nbsp;</font></font><span style=\"font-weight: bolder;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><em>sistem digital</em></font></font></span><span style=\"font-weight: bolder;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">&nbsp;&nbsp;</span></font></font></span><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">dengan Aplikasi&nbsp;</font></font><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Web Sistemku</span></font></font><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">&nbsp;sebagai alat bantu absensi</font></font></p><ol type=\"A\" style=\"font-size: 16px;\"><li><p style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Absensi dilakukan setiap hari kerja pada saat jam datang, dan dilokasi yang sudah ditetapkan.</font></font></p></li><li><p style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Absen diaplikasi&nbsp;<span style=\"font-weight: bolder;\">web Sistemku</span>&nbsp;menggunakan scan verifikasi wajah</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Bila ada Karyawan &amp; Freelance, tidak melakukan absen diaplikasi web sistemku atas kelalaiannya sendiri ( diluar kendala teknis ). Tetapi yang bersangkutan hadir untuk bekerja diwaktu tersebut, maka;</font></font></p><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 0.2in; background: transparent; break-before: auto;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Untuk&nbsp;<span style=\"font-weight: bolder;\">F</span><span style=\"font-weight: bolder;\">reelance,</span><span style=\"font-weight: bolder;\">&nbsp;masuk kategori&nbsp;</span><span style=\"font-weight: bolder;\">ijin ( mangkir )</span>. Bila dilakukan kembali dalam periode dibulan yang sama ( lebih dari 3x ), maka akan kena sanksi secara bertahap, mulai dari teguran lisan,jika berulang dibulan berikutnya akan dikenakan sanksi tegas berupa&nbsp; teguran tertulis SP 1, dan bila sudah mendapat SP 1, tetapi tetap dilakukan kembali maka sanksi teguran naik jadi SP 2, dan bila tidak ada perubahan sanksi meningkat menjadi SP 3 ( diresignkan secara sepihak ).</font></font></p><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Untuk&nbsp;<span style=\"font-weight: bolder;\">Karyawan,&nbsp;</span><span style=\"font-weight: bolder;\">masuk kategori ijin ( mangkir ).&nbsp;</span>karyawan yang tidak absen di aplikasi web sistemku dalam periode bulan yang sama lebih dari 2x, maka uang kehadirannya hangus ( dianggap terlambat absen ), Jika dalam periode bulan yg sama ( lebih dari 3x ), maka akan kena sanksi teguran lisan, jika dibulan berikutnya berulang maka dikenakan sanksi tertulis SP 1, dan bila sudah mendapat SP 1, tetap dilakukan kembali maka sanksi teguran naik jadi SP 2, dan bila tidak ada perubahan sanksi meningkat menjadi SP 3 ( diresignkan secara sepihak ).</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Bila ada Karyawan &amp; Freelance, tidak melakukan absen diaplikasi web sistemku dikarenakan&nbsp;<span style=\"font-weight: bolder;\">kendala teknis</span>, seperti error aplikasi, HP error, dsb, bisa membuat surat rekomendasi yang disetujui atasannya langsung, dan dianggap&nbsp;<span style=\"font-weight: bolder;\">hadir</span>.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span lang=\"id-ID\">Akumulasi sanksi yang didapat&nbsp;</span><span lang=\"id-ID\">akan mempengaruhi penilaian performa&nbsp;</span><span lang=\"id-ID\">yang bersangkutan&nbsp;</span><span lang=\"id-ID\">&nbsp;</span><span lang=\"id-ID\">di</span><span lang=\"id-ID\">akhir tahun.</span></font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span lang=\"id-ID\">Untuk absen freelance harian, akan dipantau oleh atasannya langsung. Bila yang bersangkutan sering terlambat, disarankan&nbsp;</span><span lang=\"id-ID\">untuk yang bersangkutan&nbsp;</span><span lang=\"id-ID\">tidak&nbsp;</span><span lang=\"id-ID\">usah&nbsp;</span><span lang=\"id-ID\">dipanggil kerja lagi.</span></font></font></p></li></ol></td></tr></tbody></table><ol type=\"A\"><li>\r\n</li></ol>', '', '2025-04-24 20:31:13', '2026-06-02 16:29:55', NULL, NULL, 17),
(282, 'IJIN', '<p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>IZIN</strong></font></font></p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in;\">\r\n<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>Izin\r\ntidak masuk kerja</strong></font></font></p><ul>\r\n	<li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Jika\r\n	ijin tidak masuk kerja, maka yang bersangkutan mengisi permohonan\r\n	ijin tidak masuk kerja yang ada diaplikasi web sistemku.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Yang\r\n	bersangkutan memberitahukan juga ke atasannya langsung ( bisa via\r\n	tlp atau chat )</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Bila\r\n	yang bersangkutan tidak ada kabar berita, maka dianggap mangkir.\r\n	Akan mempengaruhi penilaian diakhir tahun, dan performance nya akan\r\n	dievaluasi kembali.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Bila\r\n	mangkir lebih dari 1x, maka akan dikenakan sanksi teguran SP 1, jika\r\n	sudah mendapat SP 1, tetapi dilakukan kembali maka sanksinya\r\n	meningkat menjadi SP 2, dan jika berulang kembali maka sanksi naik\r\n	menjadi SP 3.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Ijin\r\n	tidak masuk kerja berbeda dengan cuti, sifatnya mutlak, dan\r\n	statusnya tidak bisa bertukar dari ijin menjadi cuti dan sebaliknya\r\n	dari cuti menjadi ijin.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Izin\r\n	tidak masuk kerja karena alasan sakit, harus menyertakan surat\r\n	keterangan sakit dari dokter dan kwintansi biaya berobat untuk claim\r\n	penggantian biaya berobat tersebut.&nbsp;</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Bila tidak menyertakan surat\r\n	dokter dan kwitansi biaya berobat, maka tunjangan kesehatannya tidak\r\n	bisa digunakan untuk claim biaya berobat tersebut.</font></font></p></li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Jika\r\n	ijin sakit tidak menyertakana surat sakit, maka akan dianggap ijin\r\n	biasa saja, bukan termasuk kategori sakit.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Jika\r\n	yang bersangkutan sakit selama 3 hari belum bisa masuk kerja, maka\r\n	atasan serta rekan kerja akan menjenguk yang bersangkutan. </font></font>\r\n	</p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Ijin\r\n	sering tidak masuk kerja, maka akan mempengaruhi peniaian diakhir\r\n	tahun</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Ijin\r\n	maksimal 3x dalam 1 bulan, bila melebihi batas ijin yang\r\n	bersangkutan akan dievaluasi dan diberikan teguran secara bertahap.</font></font></p>\r\n</li></ul><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><br>\r\n\r\n</p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"> \r\n<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>Izin\r\nmeninggalkan pekerjaan (IMP)</strong></font></font></p><p>\r\n\r\n\r\n\r\n\r\n</p><ul>\r\n	<li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Jika\r\n	akan meninggalkan pekerjaan sementara waktu, maka harus\r\n	memberitahukan ke atasannya langsung, dan harus diijinkan oleh\r\n	atasannya.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">IMP\r\n	bisa dilakukan jika karyawan telah hadir bekerja terlebih dahulu &amp;\r\n	Absen diweb sistemku saat jam masuk pagi hari.</font></font></p></li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Tidak\r\n	tercatat IMP bila dibawah batas toleransi yaitu 1 jam, bila\r\n	meninggalkan pekerjaan lebih dari 1 jam, maka dicatat IMP. </font></font>\r\n	</p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"></font></font></p><ul><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">IMP harus mengisi form pengajuan diaplikasi web sistemku ( masuk kategori ijin, dan dikolom keterangan tulis IMP ).</font></font></p></li></ul></li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Jika\r\n	sering IMP, akan mempengaruhi penilaian akhir tahun, dan performance\r\n	yang bersangkutan akan dievaluasi.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">IMP\r\n	 hanya bisa dilakukan untuk kondisi yang bersifat<strong> urgent</strong>.</font></font></p>\r\n</li></ul>', '', '2025-04-24 20:49:29', '2026-06-02 16:37:41', NULL, NULL, 17);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(283, 'CUTI', '<p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>CUTI</strong></font></font></p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in;\">\r\n<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>Cuti\r\nregular</strong></font></font></p><ul>\r\n	<li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Cuti\r\n	diberikan kepada karyawan yang telah melewati masa percobaan kerja\r\n	selama 3 bulan</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Cuti\r\n	regular diberikan pertahun sebanyak 12 kali.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Karyawan\r\n	yang belum genap 1 tahun bekerja maka jumlah cuti yg didapatkan\r\n	adalah :                                                            \r\n	                                                                    \r\n	   1 x ( jumlah bulan bekerja - masa percobaan 3 bulan ).</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Pengajuan\r\n	cuti maksimal 1 hari sebelum hari cuti, dengan mengisi Form\r\n	Pengajuan Cuti diaplikasi <strong>Web Sistemku</strong></font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in;\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Cuti\r\n	dadakan tidak diperkenankan, misal hari H tidak masuk kerja kemudian\r\n	yang bersangkutan ingin dimasukkan cuti, itu tidak bisa dilakukan,\r\n	akan dimasukkan kategori ijin biasa. </font></font>\r\n	</p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Pengajuan\r\n	cuti harus diketahui, dan disetujui atasannya langsung.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Pengambilan\r\n	cuti dalam 1 bulan hanya bisa maksimal 3 hari</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Jika\r\n	sampai akhir tahun masih ada jatah cuti yang tidak diambil maka ada\r\n	penggantian dalam bentuk kompensasi uang. </font></font>\r\n	</p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Uang\r\n	kompensasi sisa cuti, akan diberikan pada bulan pertama ditahun\r\n	berikutnya</font></font></p>\r\n</li></ul><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"> \r\n</p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>Cuti\r\nkhusus</strong></font></font></p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Setiap\r\nkaryawan berhak mendapatkan cuti khusus selain cuti regular diatas,\r\nyaitu :</font></font></p><ul>\r\n	<li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Cuti\r\n	anggota keluarga meninggal (ayah/ibu, adik/kakak, istri/suami, anak)\r\n	: 1 hari </font></font>\r\n	</p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Cuti\r\n	istri melahirkan : 1 hari</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Cuti\r\n	hamil / melahirkan : jumlah cuti disesuaikan dengan keputusan\r\n	manajemen perusahaan. Selama masa cuti tersebut, karyawan tetap\r\n	mendapatkan gaji pokok.</font></font></p>\r\n</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Cuti Menikah : 1 hari</font></font></p></li></ul><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><br>\r\n\r\n</p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>Cuti\r\nTambahan</strong></font></font></p><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><ul>\r\n	<li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Karyawan\r\n	dapat mengajukan cuti tambahan, bila saldo cutinya sudah habis\r\n	ditahun berjalan. Dengan catatan,<em> cuti tambahan berlaku/ dapat\r\n	diajukan bila kondisi sangat mendesak, dan tidak dapat ditangguhkan</em>.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Karyawan\r\n	yang mengajukan cuti tambahan, harus disetujui oleh atasannya\r\n	masing-masing. Dan dipastikan saat cuti, pekerjaan yang bersangkutan\r\n	sudah ada yang backup untuk handle pekerjaannya.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Karyawan\r\n	yang mengajukan <strong>cuti tambahan</strong>, maka akan <strong>mengurangi saldo\r\n	cutinya ditahun berikutnya</strong>.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Karyawan\r\n	yang mengajukan cuti tambahan, dapat melalui aplikasi <strong>Web Sisitemku</strong>.\r\n	Silahkan masuk ke aplikasi Web Sistemku, klik menu <strong>IJIN/CUTI</strong>, isi\r\n	kolom tipe pilih <strong>IJIN</strong>, lalu dikolom keterangan isi :  <strong>(Cuti\r\n	tambahan), </strong><strong>kemudian</strong><strong> sertakan alasannya.</strong></font></font></p></li></ul>', '', '2025-04-24 20:50:25', '2026-06-02 16:44:54', NULL, NULL, 17);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(284, 'LEMBUR', '<ul><ul><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in; background: transparent\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>LEMBUR</strong></font></font></p>\r\n</ul><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in; background: transparent\">\r\n</p><ul>\r\n	<li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Lembur\r\n	berlaku, jika karyawan masih bekerja diluar dari waktu kerja yang\r\n	telah ditentukan.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Lembur\r\n	dilakukan atas permintaan atasannya langsung.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Jika\r\n	lembur dilakukan 3 jam atau lebih maka ada tambahan uang makan\r\n	lembur Rp.10.000,-, tapi jika lemburnya harus sampai keluar kota\r\n	maka akan disesuaikan dengan kondisi yang ada</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Ketentuan\r\n	perhitungan uang lembur :</font></font></p>\r\n	<p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">   \r\n	      <font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><em>Freelance Rp.\r\n	7</em><em>,5</em><em>00</em><em>  x jumlah jam lembur&nbsp;</em></font></font></p></li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><em style=\"font-size: 10pt; font-family: Arial, sans-serif;\">Karyawan Rp. 9,000 x jumlah jam lembur</em></p></li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Untuk\r\n	lembur silahkan&nbsp;mengisi pengajuan Lembur diaplikasi\r\n	<strong>Web Sistemku,</strong> dan Atasannya mengisi data lembur bawahannya di link SS yang sudah disediakan.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Data Validasi akan direkonsil oleh tim HR</font></font></p></li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Pembayaran\r\n	uang lembur, diberikan pada saat pembayaran gaji yang bersangkutan (\r\n	disatukan ).</font></font></p></li></ul></ul>', '', '2025-04-24 20:53:52', '2026-06-02 16:49:24', NULL, NULL, 17);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(285, 'KASBON', '<p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>KASBON</strong></font></font></p><p>\r\n</p><ul>\r\n	<li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in;\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Setiap\r\n	karyawan diberikan limit untuk setiap pengajuan kasbon, yaitu 90%\r\n	dari total gaji ( diluar perhitungan bonus &amp; lemburan ), </font></font>\r\n	</p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in;\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Nilai\r\n	pengajuan kasbon harus disetujui oleh atasannya terlebih dahulu.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in;\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Karyawan\r\n	tidak bisa mengajukan kasbon, apabila karyawan tersebut masih\r\n	mempunyai kasbon yang belum selesai / belum dilunasi. </font></font>\r\n	</p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in;\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">karyawan\r\n	yang akan mengajukan kasbon mengisi form yang sudah disediakan, dan\r\n	disetujui oleh atasannya. </font></font>\r\n	</p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in;\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Pengembalian\r\n	kasbon bisa dengan cara dicicil, yaitu maksimal dalam jangka waktu 3\r\n	bulan, dengan besar minimum pengembalian perbulannya ialah 30% dari\r\n	total gaji.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in;\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Apabila\r\n	pengajuan kasbon dengan nilai kasbonnya dibawah 30% dari total nilai\r\n	gaji, maka kasbonnya akan langsung dipotongkan semua dipenggajian\r\n	bulan berikutnya.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in;\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Apabila\r\n	karyawan sudah melunasi kasbonnya, maka baru bisa mengajukan kasbon\r\n	lagi, dalam rentang waktu 1 bulan kedepan setelah pelunasan.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in;\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Data\r\n	pengajuan yang sudah diajukan, akan dikroscek serta divalidasi oleh\r\n	bag. Finance</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in;\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Bila\r\n	data sudah valid &amp; disetujui, maka akan direalisasikan maksimal\r\n	2 x 24 jam ( Hari kerja ) </font></font>\r\n	</p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in;\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Apabila\r\n	ada karyawan berhenti/ keluar kerja, tetapi masih memiiki kasbon,\r\n	maka harus diselesaikan/ dilunasi.&nbsp;</font></font>\r\n	</p>\r\n</li></ul>', '', '2025-04-29 18:49:36', '2025-04-29 18:49:52', NULL, NULL, 17),
(286, 'TUNJANGAN KARYAWAN', '<ul><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in; background: transparent\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>TUNJANGAN\r\n	KARYAWAN</strong></font></font></p>\r\n</ul><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>Tunjangan\r\nmakan</strong></font></font></p><ul>\r\n	<li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Makan\r\n	siang karyawan sudah disediakan oleh perusahan untuk hari Senin –\r\n	Jum’at.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Khusus\r\n	untuk hari sabtu makan siang diganti dengan uang cash Rp.20.000,-</font></font></p>\r\n</li></ul><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><br>\r\n\r\n</p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>Tunjangan\r\nKesehatan</strong></font></font></p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Setiap\r\nkaryawan berhak untuk mendapatkan tunjangan kesehatan dengan\r\nketentuan sbb :</font></font></p><ul>\r\n	<li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Karyawan\r\n	dengan status <strong>sudah menikah</strong>&nbsp;mendapatkan rp. 900.000,- pertahun</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Karyawan\r\n	dengan status <strong>belum menikah</strong>&nbsp;mendapatkan rp. 600.000,- pertahun</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Masa\r\n	kerja kurang dari 1 tahun nilai tunjangannya sbb :</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	             <font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><u>Masa\r\n	kerja (bulan)</u>   x   nilai tunjangan kesehatan</font></font></p>\r\n	<p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">   \r\n	                      <font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;12</font></font></p></li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Tunjangan\r\n	kesehatan tidak bisa digunakan lagi bila sudah mencapai limit</font></font></p></li></ul><ul>\r\n	<li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Sistem\r\n	penggunaannya adalah sistem reimburst, dengan menyerahkan\r\n	bukti-bukti biaya pengobatan</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Tunjangan\r\n	kesehatan bisa digunakan oleh karyawan yang bersangkutan dan\r\n	keluarganya.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Jika\r\n	sampai akhir tahun masih ada sisa yang tidak digunakan maka akan\r\n	diberikan uang tunai senilai uang tunjangan yang masih tersisa</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Pembayaran\r\n	uang tunjangan kesehatan yang tersisa dilakukan paling lambat di\r\n	bulan pertama tahun berikutnya</font></font></p>\r\n	\r\n</li></ul><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong><br></strong></font></font></p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>Tunjangan\r\nKecelakan Kerja</strong></font></font></p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Setiap\r\nkaryawan yang mengalami kecelakan selama melakukan pekerjaan maka\r\nakan mendapatkan tunjangan kecelakan kerja, kecuali kecelakaan yang\r\ndiakibatkan oleh kelalaian karyawan itu sendiri.</font></font></p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Yang\r\ndimaksud dengan kecelakaan kerja adalah kecelakaan yang menimpa\r\nseorang pegawai pada saat:</font></font></p><ul>\r\n	<li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Karyawan\r\n	meninggalkan rumah/tempat tinggalnya untuk menuju tempat kerja\r\n	dengan melalui jalan yang biasa dilaluinya.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Karyawan\r\n	bekerja atau berada ditempat kerja.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Karyawan\r\n	dalam perjalanan pulang ke rumah atau tempat tinggalnya dengan\r\n	melalui jalan yang biasa dilaluinya.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Tunjangan\r\n	kecelakan kerja berupa biaya pengobatan ditanggung oleh perusahaan\r\n	dengan nilai yang akan ditentukan kemudian oleh pihak manajemen\r\n	perusahaan sesuai dengan kondisi yang ada.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Sistem\r\n	penggunaannya adalah sistem reimburst dengan menyerahkan bukti-bukti\r\n	biaya pengobatan</font></font></p>\r\n	\r\n</li></ul><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong><br></strong></font></font></p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>Tunjangan\r\nHari Raya</strong></font></font></p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Setiap\r\nkaryawan berhak untuk mendapatkan tunjangan hari raya dengan\r\nketentuan sbb :</font></font></p><ul>\r\n	<li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Masa\r\n	kerja 1 tahun atau lebih mendapatkan 100% dari nilai perhitungan THR</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Masa\r\n	kerja kurang dari 1 tahun nilai tunjangannya sbb :</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	           <u>  <font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Masa\r\n	kerja(bulan) </font></font></u><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">   x   nilai perhitungan THR</font></font></p>\r\n	<p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">   \r\n	                   <font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;12</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Nilai\r\n	perhitungan THR akan ditentukan kemudian sesuai keputusan pihak\r\n	manajemen dan bisa berubah-rubah sesuai dengan kondisi yang ada</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Pembayaran\r\n	THR dilakukan beberapa hari sebelum hari raya idul fitri</font></font></p>\r\n</li></ul><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><br>\r\n\r\n</p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>Tunjangan\r\nKehadiran</strong></font></font></p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Setiap\r\nkaryawan berhak untuk mendapatkan tunjangan kehadiran dengan\r\nketentuan sbb:</font></font></p><ul>\r\n	<li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Karyawan\r\n	akan mendapatkan tunjangan kehadiran sebesar Rp.175.000 perbulan,\r\n	bila dalam 1 bulan full absen tanpa ada keterlambatan.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Jika\r\n	karyawan terlambat atau tidak absen 1x, maka nilai tunjangan akan\r\n	berkurang sebesar Rp. 75.000</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Jika\r\n	karyawan terlambat atau tidak absen 2x, maka tunjangan kehadirannya\r\n	akan hangus.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Keterlambatan\r\n	akan mempengaruhi penilaian diakhir tahun.</font></font></p>\r\n	\r\n</li></ul><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><br>\r\n\r\n</p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>Bonus\r\nTahunan</strong></font></font></p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Setiap\r\nkaryawan berhak untuk mendapatkan bonus tahunan yang nominalnya \r\nsesuai dengan keputusan manajemen perusahaan berdasarkan parameter\r\nsbb :</font></font></p><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><ul>\r\n	<li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Kondisi\r\n	keuangan perusahaan diakhir tahun, Lama kerja, Jabatan, Prestasi\r\n	kerja ( mencakup performance kinerja karyawan ).</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Pembayaran\r\n	bonus tahunan direalisasikan setelah data valid</font></font></p>\r\n</li></ul>', '', '2025-04-29 18:55:25', '2025-04-29 23:10:00', NULL, NULL, 17),
(287, 'PROGRAM ROHANI', '<p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>P</strong><strong>ROGRAM\r\nROHANI</strong></font></font></p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>T</strong><strong>ilawah\r\n&amp; Tahsin</strong></font></font></p><p>\r\n\r\n</p><ul>\r\n	<li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Setiap\r\n	karyawan diwajibkan untuk mengikuti tilawah rutin melalui aplikasi\r\n	yang telah ditetapkan, setiap hari minimal 1 halaman per hari,</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Data Rekapan tilawah otomatis terekap disistemku</font></font></p></li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Setiap pagi dihari kerja sebelum briefing pagi, dilaksanakan tilawah bersama disetiap divisi. ( Bisa berubah sewaktu waktu )</font></font></p></li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Untuk kegiatan Tahsin, karyawan &amp; freelance ( tetap ) akan dikelompokkan dan disesuaikan dengan kemampuan membaca Qurannya</font></font></p></li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Program\r\n	tahsin ( belajar mengaji ), berlaku untuk karyawan &amp; freelance tetap.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Tahsin dijadwalkan setiap 1 minggu sekali.</font></font></p></li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Tahsin\r\n	dijadwalkan mulai pukul 07.30 - 09.00 WIB.( Conditional )</font></font></p>\r\n</li></ul><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>Kajian\r\nRutin</strong></font></font></p><ul>\r\n	<li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Kajian\r\n	rutin dilaksanakan 2 minggu sekali </font></font>\r\n	</p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Pemateri, waktu &amp; lokasi kajian sudah ditentukan. </font></font>\r\n	</p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">SDM luar kota bisa mengikuti secara online via link yang sudah disiapkan..</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Karyawan\r\n	&amp; freelance tetap, absen melalui aplikasi yang telah ditentukan</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Kehadiran\r\n	saat kajian, dapat mempengaruhi penilaian akhir tahun</font></font></p></li></ul><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0.02in\"><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>Yaumian\r\n</strong></font></font></font></span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>Sholat\r\n5 </strong></font></font></font></span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>W</strong></font></font></font></span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>aktu\r\n</strong></font></font></font></span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>B</strong></font></font></font></span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>erjamaah</strong></font></font></font></span></p><ul>\r\n	<li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0.02in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">SDM mengisi\r\n	via sistemku, </font></font><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">maksimal\r\n	( H+2 ), karena akan terkunci otomatis</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0.02in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Leader\r\n	setiap divisi </font></font><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">akan</font></font><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">\r\n	mengingatkan timnya yang belum mengisi yaumian</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0.02in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Bila telat mengisi yaumian disistemku, maka tim HR akan merekap sesuai yang terisi, untuk keperluan data performance akhir tahun.</font></font></p></li></ul><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0.02in\"><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong><br></strong></font></font></font></span></p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0.02in\"><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>I</strong></font></font></font></span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>tikaf\r\nBulan Ramadhan</strong></font></font></font></span></p><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><ul>\r\n	<li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0.02in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Karyawan\r\n	&amp; Freelance mengikuti kegiatan Itikaf dimesjid yang telah\r\n	ditentukan.</font></font></p>\r\n	</li><li><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0.02in\">\r\n	<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Selama\r\n	mengikuti kegiatan itikaf, karyawan &amp; Freelance harus mengikuti\r\n	aturan yang telah ditentukan oleh panitia Itikaf,&nbsp;</font></font></p></li></ul><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0.02in\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong><br></strong></font></font></p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0.02in\">\r\n<font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>Baca\r\nSurat Alkahf</strong></font></font></p><p>\r\n</p><ul><li><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Dibaca\r\nsetiap hari Jum’at ( diusahakan baca full sampai akhir surat )</font></font></li></ul>', '', '2025-04-29 20:01:19', '2026-09-04 14:50:37', NULL, NULL, 18);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(288, 'PROGRAM OLAHRAGA', '<p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">PROGRAM OLAHRAGA</span></font></font></p><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Futsal / Minsoc</span></font></font></p><ul><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Setiap karyawan diwajibkan untuk mengikuti kegiatan olahraga futsal / Minsoc1 minggu sekali, yang diadakan oleh pihak perusahaan.</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Wajib menggunakan celana panjang</span></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Wajib mengikuti aturan Futsal / Minsoc sesuai arahan dari PIC Program</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Karyawan yang tidak bisa hadir harus memberitahukan sebelumnya kepada ketua timnya.</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jika karyawan tidak hadir tanpa pemberitahuan sebelumnya atau dengan alasan yang tidak sesuai maka akan mempengaruhi penilaian diakhir tahun.</font></font></p></li></ul><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><br></p><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Lari</span></font></font></p><ul><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Setiap karyawan diwajibkan untuk lari 2x periode dalam 1 minggu</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Min. jarak tempuh dalam 1x periode ialah 4 km, dengan kecepatan ( pace ) min. 8</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jadwal lari Periode 1, hari Senin – Rabu, bila hari rabu belum maelaksanakan lari, maka diberikan toleransi dihari kamis pagi, atau saat jam istirahat.</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jadwal lari periode 2, hari Jum’at – Minggu</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Lari menggunakan aplikasi STRAVA.</span></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Data lari otomatis terekap disistemku</span></font></p></li></ul><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\"><br></span></font></font></p><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Timbang Badan</span></font></font></p><ul><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Kegiatan timbang badan dijadwalkan 1 bulan sekali</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Input data timbang badan ke sistemku</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Hasil timbang badan yang masuk kategori obesitas, akan masuk program penurunan berat badan</font></font></p></li></ul><p><font face=\"Arial, sans-serif\"><br></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Sepeda</span></font></font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan yang tinggal dalam jarak 1 hingga 7,5 kilometer dari kantor diwajibkan menggunakan sepeda untuk berangkat kerja.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Dalam satu minggu kerja (Senin sampai Sabtu), karyawan diminta menggunakan sepeda minimal 3 kali. Sisanya bebas.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika dalam seminggu karyawan tidak memenuhi penggunaan sepeda sebanyak 3 kali, maka akan dikenakan sanksi berupa iqob sepeda.&nbsp;</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan yang masuk dalam ketentuan ini wajib memiliki sepeda.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika belum memiliki sepeda, perusahaan menyediakan bantuan subsidi sebesar 50% dari harga sepeda.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Apabila karyawan berhenti bekerja, maka subsidi tersebut wajib dikembalikan. Pengembalian akan dilakukan melalui pemotongan dari hak karyawan yang masih tersisa.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Subsidi sebesar 50% wajib dikembalikan kepada perusahaan apabila karyawan mengundurkan diri atau diberhentikan sebelum masa kerja mencapai satu tahun. Namun, jika karyawan telah bekerja selama lebih dari satu tahun, maka subsidi 50% tersebut tidak perlu dikembalikan dan apabila selama bekerja tidak boleh dijual atau di gadai.<br></font></font><br></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\"><span style=\"font-weight: bolder;\">Penyesuaian program sepeda di pekan yang bertepatan dengan PHBN/ Tanggal Merah, ataupun cuti bagi SDM yang berkewajiban menjalankan Program :&nbsp;</span></span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Kondisi Pertama : Jika ada tanggal merah di pekan berjalan,&nbsp;</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">kewajiban sepeda berkurang sesuai tanggal merah di pekan tersebut</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">misal : Tanggal 1 -6, Tanggal 2 nya Tanggal merah, Maka kewajiban bersepeda hanya menjadi 2 kali</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">dan berlaku akumulatif,&nbsp;</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">(jika lebih dari 1 maka kewajiban bersepda berkurang sesuai banyakna tanggal merah dipekan berjalan)</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Kondisi Kedua : Jika Karyawan mengambil cuti dipekan berjalan</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Kewajiban sepeda berkurang sesuai banyakna cuti yang diambil dipekan berjalan</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">misal : Tanggal 1-6 , Ambil 1 hari cuti maka kewajiban bersepedannya berkurang 1x, dan berlaku akumulatif,</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">(jika cuti diambil lebih dari 1 hari maka kewajiban bersepeda berkurang sesuai banyaknya cuti yang diambil dipekan berjalan)</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Kondisi Ketiga Jika Karyawan Ambil cuti di pekan yang ada tanggal merahnya</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Kewajiban sepeda berkurang sesuai banyaknya cuti dan tanggal merah di pekan berjalan</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font style=\"box-sizing: inherit; font-size: 13.3333px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">dan berlaku akumulatif.</span></font></p></li></ul>', '', '2025-04-29 20:26:19', '2026-09-04 14:37:53', NULL, NULL, 18);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(289, 'PROGRAM SOSIAL', '<p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">PROGRAM SOSIAL</span></font></font></p><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Donor Darah</span></font></font></p><ul><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Setiap karyawan diwajibkan untuk mengikuti kegiatan Donor Darah yang diadakan oleh pihak perusahaan</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Donor darah dilakukan rutin minimal 2 bulan sekali.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Waktu, dan tempat kegiatan ditentukan oleh pihak perusahaan</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Karyawan yang tidak bisa hadir / tidak lolos donor darah maka harus mencoba lagi donor darah dicabang PMI terdekat.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Batas Waktu percobaan ulang donor, adalah 7 hari dari waktu kegiatan donor darah massal</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jika dipercobaan donor ulang tetap tidak berhasil dan batas waktunya sudah habis, maka tidak perlu mencoba donor lagi</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">kegiatan donor darah dapat mempengaruhi penilaian diakhir tahun.</font></font></p></li></ul><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><br></p><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Bakti Sosial</span></font></font></p><ul><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Kegiatan Jumsih, kegiatan bakti sosial yang dlaksanakan setiap hari jumat pagi dilingkungan sekitar kantor.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Peserta jumsih terdiri dari karyawan &amp; freelance ( opsional )</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Peserta jumsih akan dikelompokkan, dan ditentukan lokasi pelaksanaannya.</font></font></p></li></ul>', '', '2025-04-29 20:26:40', '2025-05-04 01:25:04', NULL, NULL, 18);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(290, 'TEGURAN DAN SURAT PERINGATAN', '<p align=\"justify\" style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\">\r\n<font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>SANKSI</strong></font></font></font></p><p align=\"justify\" style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\">\r\n<font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>Teguran\r\nLisan</strong></font></font></font></p><p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\">\r\n<font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Jika\r\nmelanggar aturan yang telah ditetapkan, maka akan diberikan teguran\r\nlisan terlebih dahulu, dan sanksi akan meningkat bila masih melakukan\r\npelanggaran kembali.</font></font></font></p><ul>\r\n	<p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\">\r\n	</p>\r\n</ul><p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\">\r\n<font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>SP\r\n1</strong></font></font></font></p><p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\">\r\n<font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Jika\r\nkaryawan melakukan pelanggaran kembali secara berulang, setelah\r\ndiberikan teguran lisan, maka akan mendapatkan SP 1 dengan ketentuan\r\nsbb :</font></font></font></p><p style=\"line-height: 100%; margin-bottom: 0.02in;\">\r\n<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Mengisi\r\n</font></font></font></span><em><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><span style=\"font-style: normal\"><strong>Form\r\nSP 1</strong></span></font></font></font></span></em></p><p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\">\r\n<font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Sanki\r\nyang diterima :</font></font></font></p><ul>\r\n	<li><p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\">\r\n	<font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Segala\r\n	bentuk promosi dan kenaikan gaji akan ditangguhkan</font></font></font></p>\r\n	</li><li><p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\">\r\n	<font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">mengurangi\r\n	penilaian bonus akhir tahun</font></font></font></p>\r\n	</li><li><p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\">\r\n	<font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Peringatan\r\n	ini akan dihapuskan apabila selama 1 (satu) bulan yang bersangkutan\r\n	tidak melakukan pelanggaran</font></font></font></p>\r\n	</li><li><p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\">\r\n	<font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Bila\r\n	dalam masa hukuman melakukan pelanggaran kembali, maka statusnya\r\n	meningkat menjadi SP 2</font></font></font></p>\r\n</li></ul><p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\"><br>\r\n\r\n</p><p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\">\r\n<font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>SP\r\n2</strong></font></font></font></p><p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\">\r\n<font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Jika\r\nkaryawan melakukan pelanggaran kembali setelah mendapatkan SP 1 maka\r\nakan mendapatkan SP 2 dengan ketentuan sbb :</font></font></font></p><p style=\"line-height: 100%; margin-bottom: 0.02in;\">\r\n<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Mengisi</font></font></font></span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">\r\n</font></font></font></span><em><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><span style=\"font-style: normal\"><strong>Form\r\nSP 2</strong></span></font></font></font></span></em></p><p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\">\r\n<font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Sanki\r\nyang diterima :</font></font></font></p><ul>\r\n	<li><p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\">\r\n	<font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Segala\r\n	bentuk promosi dan kenaikan gaji akan ditangguhkan</font></font></font></p>\r\n	</li><li><p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\">\r\n	<font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">mengurangi\r\n	penilaian bonus akhir tahun</font></font></font></p>\r\n	</li><li><p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\">\r\n	<font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Peringatan\r\n	ini akan dihapuskan apabila selama 2 (dua) bulan yang bersangkutan\r\n	tidak melakukan pelanggaran</font></font></font></p>\r\n	</li><li><p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\">\r\n	<font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Bila\r\n	dalam masa hukuman melakukan pelanggaran kembali, maka statusnya\r\n	meningkat menjadi SP 3</font></font></font></p>\r\n</li></ul><p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\"><br>\r\n\r\n</p><p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\">\r\n<font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\"><strong>SP\r\n3</strong></font></font></font></p><p style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 100%; margin-bottom: 0.02in;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt\">Jika Karyawan\r\nyang mendapatkan SP 3, silahkan mengundurkan diri ( resign ).</font></font></font></p><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p align=\"justify\" style=\"line-height: 100%; margin-bottom: 0in\"><br>\r\n\r\n</p>', '', '2025-04-29 23:43:15', '2025-05-04 01:19:13', NULL, NULL, 19),
(291, 'TATA TERTIB', '<p style=\"box-sizing: inherit; margin-bottom: 1rem; background-color: rgb(233, 237, 242);\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\">TATA TERTIB</font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Mentaati ketentuan waktu kerja</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Seluruh karyawan wajib untuk mengikuti tilawah pagi &amp; briefing pagi</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan yang berada di kantor pada saat jam shalat (dhuhur &amp; ashar) berkewajiban untuk mengikuti shalat berjamaah (khusus ikhwan shalat berjamaah di masjid)</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Tidak boleh mendengarkan musik saat jam kerja.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Tidak boleh menonton youtube, tiktok, dan download pribadi &amp; lainnya, saat jam kerja.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Tidak boleh merokok bagi karyawan &amp; freelance</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Tidak boleh bergadang untuk kepentingan &amp; kesenangan diri sendiri, misal bermain game, dan lainnya</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Dilarang berbuat asusila dilingkungan perusahaan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">dilarang melakukan manipulasi data perusahaan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Tidak diperbolehkan melakukan kegiatan usaha pribadi yang sama dengan jenis bisnis perusahaan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Dilarang melakukan transaksi ribawi</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Setiap hari sabtu diwajibkan sholat dzuhur berjamaah terlebih dahulu sebelum pulang.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Setiap waktu sholat, saat tiba dimesjid harus langsung bergegas untuk masuk kedalam mesjid, tidak boleh duduk atau mengobrol terlebih dahulu diteras mesjid.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Seluruh karyawan berkewajiban untuk menjaga kebersihan dan kerapihan, seperti : area tempat kerjanya, tempat makan dan minum, sandal/sepatu disimpan pada tempatnya, dan parkir kendaraan ditempat yang telah ditentukan.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Melaksanakan tugas/pekerjaan dengan sebaik-baiknya, penuh pengabdian, kesadaran dan bertanggung jawab.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Menjaga &amp; tidak membocorkan rahasia perusahaan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Memelihara dan meningkatkan keutuhan, kekompakan dan persatuan untuk menciptakan suasana kerja yang baik sesuai dengan harapan perusahaan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Menggunakan dan memelihara barang-barang milik perusahaan dengan sebaik-baiknya.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Berpenampilan rapih dan bersih.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">bersikap dan bertingkah laku sopan santun terhadap masyarakat dan sesama karyawan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Bersikap sopan, jujur dan selalu mentaati perintah atasan dalam melakukan pekerjaannya serta selalu meningkatkan efisiensi dan produktifitas kerja</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Tidak melakukan perbuatan yang dapat merusak atau merugikan nama baik perusahaan, pimpinan atau teman sekerja, dan harus memelihara kerjasama yang baik diantara karyawan untuk menciptakan ketenangan kerja dan memelihara ketertiban dalam perusahaan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Menggunakan, menjalankan atau menyimpan dengan baik semua peralatan atau mesin-mesin, bahan-bahan atau surat-surat berharga milik perusahaan yang dipercayakan kepadanya</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Bertanggung jawab atas semua barang atau harta milik perusahaan yang dipercayakan kepadanya dan harus segera melaporkan kehilangan atau kerusakan yang terjadi terhadap barang-barang atau harta milik perusahaan tersebut kepada atasannya.</font></font></p></li></ul>', '', '2025-05-05 20:38:09', '2025-05-05 20:38:09', NULL, NULL, 23);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(292, 'TUNJANGAN KARYAWAN', '<ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px; background: transparent;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">TUNJANGAN KARYAWAN</span></font></font></p></ul><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Tunjangan makan</span></font></font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Makan siang karyawan sudah disediakan oleh perusahan untuk hari Senin – Jum’at.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Khusus untuk hari sabtu makan siang diganti dengan uang cash Rp.20.000,-</font></font></p></li></ul><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><br style=\"box-sizing: inherit;\"></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Tunjangan Kesehatan</span></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Setiap karyawan berhak untuk mendapatkan tunjangan kesehatan dengan ketentuan sbb :</font></font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan dengan status&nbsp;<span style=\"box-sizing: inherit; font-weight: bolder;\">sudah menikah</span>&nbsp;mendapatkan rp. 900.000,- pertahun</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan dengan status&nbsp;<span style=\"box-sizing: inherit; font-weight: bolder;\">belum menikah</span>&nbsp;mendapatkan rp. 600.000,- pertahun</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Masa kerja kurang dari 1 tahun nilai tunjangannya sbb :</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><u style=\"box-sizing: inherit;\">Masa kerja (bulan)</u>&nbsp;x nilai tunjangan kesehatan</font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;12</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Tunjangan kesehatan tidak bisa digunakan lagi bila sudah mencapai limit</font></font></p></li></ul><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Sistem penggunaannya adalah sistem reimburst, dengan menyerahkan bukti-bukti biaya pengobatan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Tunjangan kesehatan bisa digunakan oleh karyawan yang bersangkutan dan keluarganya.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika sampai akhir tahun masih ada sisa yang tidak digunakan maka akan diberikan uang tunai senilai uang tunjangan yang masih tersisa</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Pembayaran uang tunjangan kesehatan yang tersisa dilakukan paling lambat di bulan pertama tahun berikutnya</font></font></p></li></ul><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\"><br style=\"box-sizing: inherit;\"></span></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Tunjangan Kecelakan Kerja</span></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Setiap karyawan yang mengalami kecelakan selama melakukan pekerjaan maka akan mendapatkan tunjangan kecelakan kerja, kecuali kecelakaan yang diakibatkan oleh kelalaian karyawan itu sendiri.</font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Yang dimaksud dengan kecelakaan kerja adalah kecelakaan yang menimpa seorang pegawai pada saat:</font></font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan meninggalkan rumah/tempat tinggalnya untuk menuju tempat kerja dengan melalui jalan yang biasa dilaluinya.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan bekerja atau berada ditempat kerja.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan dalam perjalanan pulang ke rumah atau tempat tinggalnya dengan melalui jalan yang biasa dilaluinya.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Tunjangan kecelakan kerja berupa biaya pengobatan ditanggung oleh perusahaan dengan nilai yang akan ditentukan kemudian oleh pihak manajemen perusahaan sesuai dengan kondisi yang ada.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Sistem penggunaannya adalah sistem reimburst dengan menyerahkan bukti-bukti biaya pengobatan</font></font></p></li></ul><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\"><br style=\"box-sizing: inherit;\"></span></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Tunjangan Hari Raya</span></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Setiap karyawan berhak untuk mendapatkan tunjangan hari raya dengan ketentuan sbb :</font></font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Masa kerja 1 tahun atau lebih mendapatkan 100% dari nilai perhitungan THR</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Masa kerja kurang dari 1 tahun nilai tunjangannya sbb :</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><u style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Masa kerja(bulan)&nbsp;</font></font></u><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">x nilai perhitungan THR</font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;12</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Nilai perhitungan THR akan ditentukan kemudian sesuai keputusan pihak manajemen dan bisa berubah-rubah sesuai dengan kondisi yang ada</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Pembayaran THR dilakukan beberapa hari sebelum hari raya idul fitri</font></font></p></li></ul><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><br style=\"box-sizing: inherit;\"></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Tunjangan Kehadiran</span></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Setiap karyawan berhak untuk mendapatkan tunjangan kehadiran dengan ketentuan sbb:</font></font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan akan mendapatkan tunjangan kehadiran sebesar Rp.175.000 perbulan, bila dalam 1 bulan full absen tanpa ada keterlambatan.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika karyawan terlambat atau tidak absen 1x, maka nilai tunjangan akan berkurang sebesar Rp. 75.000</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika karyawan terlambat atau tidak absen 2x, maka tunjangan kehadirannya akan hangus.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Keterlambatan akan mempengaruhi penilaian diakhir tahun.</font></font></p></li></ul><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><br style=\"box-sizing: inherit;\"></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Bonus Tahunan</span></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Setiap karyawan berhak untuk mendapatkan bonus tahunan yang nominalnya sesuai dengan keputusan manajemen perusahaan berdasarkan parameter sbb :</font></font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Kondisi keuangan perusahaan diakhir tahun, Lama kerja, Jabatan, Prestasi kerja ( mencakup performance kinerja karyawan ).</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Pembayaran bonus tahunan direalisasikan setelah data valid</font></font></p></li></ul>', '', '2025-05-05 20:40:10', '2025-05-05 20:40:10', NULL, NULL, 22);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(293, 'KASBON', '<p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">KASBON</span></font></font></p><ul style=\"box-sizing: inherit;\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Setiap karyawan diberikan limit untuk setiap pengajuan kasbon, yaitu 90% dari total gaji ( diluar perhitungan bonus &amp; lemburan ),</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Nilai pengajuan kasbon harus disetujui oleh atasannya terlebih dahulu.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan tidak bisa mengajukan kasbon, apabila karyawan tersebut masih mempunyai kasbon yang belum selesai / belum dilunasi.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">karyawan yang akan mengajukan kasbon mengisi form yang sudah disediakan, dan disetujui oleh atasannya.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Pengembalian kasbon bisa dengan cara dicicil, yaitu maksimal dalam jangka waktu 3 bulan, dengan besar minimum pengembalian perbulannya ialah 30% dari total gaji.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Apabila pengajuan kasbon dengan nilai kasbonnya dibawah 30% dari total nilai gaji, maka kasbonnya akan langsung dipotongkan semua dipenggajian bulan berikutnya.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Apabila karyawan sudah melunasi kasbonnya, maka baru bisa mengajukan kasbon lagi, dalam rentang waktu 1 bulan kedepan setelah pelunasan.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Data pengajuan yang sudah diajukan, akan dikroscek serta divalidasi oleh bag. Finance</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Bila data sudah valid &amp; disetujui, maka akan direalisasikan maksimal 2 x 24 jam ( Hari kerja )</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Apabila ada karyawan berhenti/ keluar kerja, tetapi masih memiiki kasbon, maka harus diselesaikan/ dilunasi.&nbsp;</font></font></p></li></ul>', '', '2025-05-05 20:41:30', '2025-05-05 20:41:30', NULL, NULL, 22);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(294, 'LEMBUR', '<ul style=\"box-sizing: inherit;\"><ul style=\"box-sizing: inherit;\"><ul><ul><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px; background: transparent;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">LEMBUR</span></font></font></p></ul><ul><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Lembur berlaku, jika karyawan masih bekerja diluar dari waktu kerja yang telah ditentukan.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Lembur dilakukan atas permintaan atasannya langsung.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jika lembur dilakukan 3 jam atau lebih maka ada tambahan uang makan lembur Rp.10.000,-, tapi jika lemburnya harus sampai keluar kota maka akan disesuaikan dengan kondisi yang ada</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Ketentuan perhitungan uang lembur :</font></font></p><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><em>Freelance Rp. 7</em><em>,5</em><em>00</em><em>&nbsp;x jumlah jam lembur&nbsp;</em></font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><em style=\"font-size: 10pt; font-family: Arial, sans-serif;\">Karyawan Rp. 9,000 x jumlah jam lembur</em></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Untuk lembur silahkan&nbsp;mengisi pengajuan Lembur diaplikasi&nbsp;<span style=\"font-weight: bolder;\">Web Sistemku,</span>&nbsp;dan&nbsp;Atasannya mengisi data lembur bawahannya di link SS yang sudah disediakan.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Data Validasi akan direkonsil oleh tim HR</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Pembayaran uang lembur, diberikan pada saat pembayaran gaji yang bersangkutan ( disatukan ).</font></font></p></li></ul></ul></ul></ul>', '', '2025-05-05 20:42:59', '2026-06-02 16:50:23', NULL, NULL, 22);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(295, 'CUTI', '<p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">CUTI</span></font></font></p><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Cuti regular</span></font></font></p><ul><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Cuti diberikan kepada karyawan yang telah melewati masa percobaan kerja selama 3 bulan</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Cuti regular diberikan pertahun sebanyak 12 kali.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Karyawan yang belum genap 1 tahun bekerja maka jumlah cuti yg didapatkan adalah : 1 x ( jumlah bulan bekerja - masa percobaan 3 bulan ).</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Pengajuan cuti maksimal 1 hari sebelum hari cuti, dengan mengisi Form Pengajuan Cuti diaplikasi&nbsp;<span style=\"font-weight: bolder;\">Web Sistemku</span></font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Cuti dadakan tidak diperkenankan, misal hari H tidak masuk kerja kemudian yang bersangkutan ingin dimasukkan cuti, itu tidak bisa dilakukan, akan dimasukkan kategori ijin biasa.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Pengajuan cuti harus diketahui, dan disetujui atasannya langsung.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Pengambilan cuti dalam 1 bulan hanya bisa maksimal 3 hari</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jika sampai akhir tahun masih ada jatah cuti yang tidak diambil maka ada penggantian dalam bentuk kompensasi uang.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Uang kompensasi sisa cuti, akan diberikan pada bulan pertama ditahun berikutnya</font></font></p></li></ul><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Cuti khusus</span></font></font></p><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Setiap karyawan berhak mendapatkan cuti khusus selain cuti regular diatas, yaitu :</font></font></p><ul><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Cuti anggota keluarga meninggal (ayah/ibu, adik/kakak, istri/suami, anak) : 1 hari</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Cuti istri melahirkan : 1 hari</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Cuti hamil / melahirkan : jumlah cuti disesuaikan dengan keputusan manajemen perusahaan. Selama masa cuti tersebut, karyawan tetap mendapatkan gaji pokok.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Cuti Menikah : 1 hari</font></font></p></li></ul><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><br></p><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Cuti Tambahan</span></font></font></p><ul><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Karyawan dapat mengajukan cuti tambahan, bila saldo cutinya sudah habis ditahun berjalan. Dengan catatan,<em>&nbsp;cuti tambahan berlaku/ dapat diajukan bila kondisi sangat mendesak, dan tidak dapat ditangguhkan</em>.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Karyawan yang mengajukan cuti tambahan, harus disetujui oleh atasannya masing-masing. Dan dipastikan saat cuti, pekerjaan yang bersangkutan sudah ada yang backup untuk handle pekerjaannya.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Karyawan yang mengajukan&nbsp;<span style=\"font-weight: bolder;\">cuti tambahan</span>, maka akan&nbsp;<span style=\"font-weight: bolder;\">mengurangi saldo cutinya ditahun berikutnya</span>.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Karyawan yang mengajukan cuti tambahan, dapat melalui aplikasi&nbsp;<span style=\"font-weight: bolder;\">Web Sisitemku</span>. Silahkan masuk ke aplikasi Web Sistemku, klik menu&nbsp;<span style=\"font-weight: bolder;\">IJIN/CUTI</span>, isi kolom tipe pilih&nbsp;<span style=\"font-weight: bolder;\">IJIN</span>, lalu dikolom keterangan isi :&nbsp;<span style=\"font-weight: bolder;\">(Cuti tambahan),&nbsp;</span><span style=\"font-weight: bolder;\">kemudian</span><span style=\"font-weight: bolder;\">&nbsp;sertakan alasannya.</span></font></font></p></li></ul>', '', '2025-05-05 20:55:56', '2026-06-02 16:46:03', NULL, NULL, 22),
(296, 'IJIN', '<p align=\"justify\" style=\"margin-bottom: 0in; font-size: 16px; background-color: oklab(0.98 0 0 / 0.5); line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">IZIN</span></font></font></p><p align=\"justify\" style=\"margin-bottom: 0in; font-size: 16px; background-color: oklab(0.98 0 0 / 0.5); line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Izin tidak masuk kerja</span></font></font></p><ul style=\"font-size: 16px; background-color: oklab(0.98 0 0 / 0.5);\"><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jika ijin tidak masuk kerja, maka yang bersangkutan mengisi permohonan ijin tidak masuk kerja yang ada diaplikasi web sistemku.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Yang bersangkutan memberitahukan juga ke atasannya langsung ( bisa via tlp atau chat )</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Bila yang bersangkutan tidak ada kabar berita, maka dianggap mangkir. Akan mempengaruhi penilaian diakhir tahun, dan performance nya akan dievaluasi kembali.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Bila mangkir lebih dari 1x, maka akan dikenakan sanksi teguran SP 1, jika sudah mendapat SP 1, tetapi dilakukan kembali maka sanksinya meningkat menjadi SP 2, dan jika berulang kembali maka sanksi naik menjadi SP 3.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Ijin tidak masuk kerja berbeda dengan cuti, sifatnya mutlak, dan statusnya tidak bisa bertukar dari ijin menjadi cuti dan sebaliknya dari cuti menjadi ijin.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Izin tidak masuk kerja karena alasan sakit, harus menyertakan surat keterangan sakit dari dokter dan kwintansi biaya berobat untuk claim penggantian biaya berobat tersebut.&nbsp;</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Bila tidak menyertakan surat dokter dan kwitansi biaya berobat, maka tunjangan kesehatannya tidak bisa digunakan untuk claim biaya berobat tersebut.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jika ijin sakit tidak menyertakana surat sakit, maka akan dianggap ijin biasa saja, bukan termasuk kategori sakit.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jika yang bersangkutan sakit selama 3 hari belum bisa masuk kerja, maka atasan serta rekan kerja akan menjenguk yang bersangkutan.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Ijin sering tidak masuk kerja, maka akan mempengaruhi peniaian diakhir tahun</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Ijin maksimal 3x dalam 1 bulan, bila melebihi batas ijin yang bersangkutan akan dievaluasi dan diberikan teguran secara bertahap.</font></font></p></li></ul><p align=\"justify\" style=\"margin-bottom: 0in; font-size: 16px; background-color: oklab(0.98 0 0 / 0.5); line-height: 16px;\"><br></p><p align=\"justify\" style=\"margin-bottom: 0in; font-size: 16px; background-color: oklab(0.98 0 0 / 0.5); line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Izin meninggalkan pekerjaan (IMP)</span></font></font></p><ul style=\"font-size: 16px; background-color: oklab(0.98 0 0 / 0.5);\"><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jika akan meninggalkan pekerjaan sementara waktu, maka harus memberitahukan ke atasannya langsung, dan harus diijinkan oleh atasannya.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">IMP bisa dilakukan jika karyawan telah hadir bekerja terlebih dahulu &amp; Absen diweb sistemku saat jam masuk pagi hari.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Tidak tercatat IMP bila dibawah batas toleransi yaitu 1 jam, bila meninggalkan pekerjaan lebih dari 1 jam, maka dicatat IMP.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"></font></font></p><ul><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">IMP harus mengisi form pengajuan diaplikasi web sistemku ( masuk kategori ijin, dan dikolom keterangan tulis IMP ).</font></font></p></li></ul></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jika sering IMP, akan mempengaruhi penilaian akhir tahun, dan performance yang bersangkutan akan dievaluasi.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">IMP hanya bisa dilakukan untuk kondisi yang bersifat<span style=\"font-weight: bolder;\">&nbsp;urgent</span>.</font></font></p></li></ul>', '', '2025-05-05 20:57:27', '2026-06-02 16:39:32', NULL, NULL, 22),
(297, 'ABSENSI', '<p style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">ABSENSI</span></font></font></p><table class=\"table table-zebra w-full text-base [&amp;_a]:text-blue-600\" style=\"width: 1322.47px; border-spacing: 0px; border-radius: 8px; font-size: medium; line-height: 1.5;\"><tbody><tr class=\"bg-base-200/50\" style=\"background-color: oklab(0.98 0 0 / 0.5);\"><td colspan=\"2\" class=\"py-3\" style=\"padding-block: 12px;\"><p style=\"font-size: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Absensi menggunakan&nbsp;</font></font><span style=\"font-weight: bolder;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><em>sistem digital</em></font></font></span><span style=\"font-weight: bolder;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">&nbsp;&nbsp;</span></font></font></span><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">dengan Aplikasi&nbsp;</font></font><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Web Sistemku</span></font></font><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">&nbsp;sebagai alat bantu absensi</font></font></p><ol type=\"A\" style=\"font-size: 16px;\"><li><p style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Absensi dilakukan setiap hari kerja pada saat jam datang, dan dilokasi yang sudah ditetapkan.</font></font></p></li><li><p style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Absen diaplikasi&nbsp;<span style=\"font-weight: bolder;\">web Sistemku</span>&nbsp;menggunakan scan verifikasi wajah</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Bila ada Karyawan &amp; Freelance, tidak melakukan absen diaplikasi web sistemku atas kelalaiannya sendiri ( diluar kendala teknis ). Tetapi yang bersangkutan hadir untuk bekerja diwaktu tersebut, maka;</font></font></p><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 0.2in; background: transparent; break-before: auto;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Untuk&nbsp;<span style=\"font-weight: bolder;\">F</span><span style=\"font-weight: bolder;\">reelance,</span><span style=\"font-weight: bolder;\">&nbsp;masuk kategori&nbsp;</span><span style=\"font-weight: bolder;\">ijin ( mangkir )</span>. Bila dilakukan kembali dalam periode dibulan yang sama ( lebih dari 3x ), maka akan kena sanksi secara bertahap, mulai dari teguran lisan,jika berulang dibulan berikutnya akan dikenakan sanksi tegas berupa&nbsp; teguran tertulis SP 1, dan bila sudah mendapat SP 1, tetapi tetap dilakukan kembali maka sanksi teguran naik jadi SP 2, dan bila tidak ada perubahan sanksi meningkat menjadi SP 3 ( diresignkan secara sepihak ).</font></font></p><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Untuk&nbsp;<span style=\"font-weight: bolder;\">Karyawan,&nbsp;</span><span style=\"font-weight: bolder;\">masuk kategori ijin ( mangkir ).&nbsp;</span>karyawan yang tidak absen di aplikasi web sistemku dalam periode bulan yang sama lebih dari 2x, maka uang kehadirannya hangus ( dianggap terlambat absen ), Jika dalam periode bulan yg sama ( lebih dari 3x ), maka akan kena sanksi teguran lisan, jika dibulan berikutnya berulang maka dikenakan sanksi tertulis SP 1, dan bila sudah mendapat SP 1, tetap dilakukan kembali maka sanksi teguran naik jadi SP 2, dan bila tidak ada perubahan sanksi meningkat menjadi SP 3 ( diresignkan secara sepihak ).</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Bila ada Karyawan &amp; Freelance, tidak melakukan absen diaplikasi web sistemku dikarenakan&nbsp;<span style=\"font-weight: bolder;\">kendala teknis</span>, seperti error aplikasi, HP error, dsb, bisa membuat surat rekomendasi yang disetujui atasannya langsung, dan dianggap&nbsp;<span style=\"font-weight: bolder;\">hadir</span>.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span lang=\"id-ID\">Akumulasi sanksi yang didapat&nbsp;</span><span lang=\"id-ID\">akan mempengaruhi penilaian performa&nbsp;</span><span lang=\"id-ID\">yang bersangkutan&nbsp;</span><span lang=\"id-ID\">&nbsp;</span><span lang=\"id-ID\">di</span><span lang=\"id-ID\">akhir tahun.</span></font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span lang=\"id-ID\">Untuk absen freelance harian, akan dipantau oleh atasannya langsung. Bila yang bersangkutan sering terlambat, disarankan&nbsp;</span><span lang=\"id-ID\">untuk yang bersangkutan&nbsp;</span><span lang=\"id-ID\">tidak&nbsp;</span><span lang=\"id-ID\">usah&nbsp;</span><span lang=\"id-ID\">dipanggil kerja lagi.</span></font></font></p></li></ol></td></tr></tbody></table>', '', '2025-05-05 20:58:08', '2026-06-02 16:31:26', NULL, NULL, 22),
(298, 'HARI &amp;JAM KERJA', '<p style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Hari Kerja</span></font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Hari kerja dalam 1 minggu 6 hari (senin – sabtu)</font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><br style=\"box-sizing: inherit;\"></p><p style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Jam Kerja</span></font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Senin – Jum’at : pkl.08.30 – 17.00 WIB</font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Sabtu : pkl.08.00 – 12.00 WIB</font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Istirahat 1 jam mulai pkl.12.00 – 13.00 WIB</font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika karyawan masih bekerja diluar waktu kerja yang telah ditentukan dan atas permintaan atasannya langsung, maka kelebihan jam kerja tersebut dihitung sebagai lembur.</font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><span style=\"box-sizing: inherit; font-weight: bolder;\"><br style=\"box-sizing: inherit;\"></span></p><p style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Libur Kerja</span></font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Hari ahad dan hari libur nasional</font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Libur hari raya idul fitri ditentukan kemudian disesuaikan dengan kondisi yang ada</font></font></p>', '', '2025-05-05 20:58:45', '2025-05-05 20:58:45', NULL, NULL, 22),
(299, 'PROGRAM SOSIAL', '<p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">PROGRAM SOSIAL</span></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Donor Darah</span></font></font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Setiap karyawan diwajibkan untuk mengikuti kegiatan Donor Darah yang diadakan oleh pihak perusahaan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Donor darah dilakukan rutin minimal 2 bulan sekali.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Waktu, dan tempat kegiatan ditentukan oleh pihak perusahaan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan yang tidak bisa hadir / tidak lolos donor darah maka harus mencoba lagi donor darah dicabang PMI terdekat.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Batas Waktu percobaan ulang donor, adalah 7 hari dari waktu kegiatan donor darah massal</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika dipercobaan donor ulang tetap tidak berhasil dan batas waktunya sudah habis, maka tidak perlu mencoba donor lagi</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">kegiatan donor darah dapat mempengaruhi penilaian diakhir tahun.</font></font></p></li></ul><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><br style=\"box-sizing: inherit;\"></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Bakti Sosial</span></font></font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Kegiatan Jumsih, kegiatan bakti sosial yang dlaksanakan setiap hari jumat pagi dilingkungan sekitar kantor.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Peserta jumsih terdiri dari karyawan &amp; freelance ( opsional )</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Peserta jumsih akan dikelompokkan, dan ditentukan lokasi pelaksanaannya.</font></font></p></li></ul>', '', '2025-05-05 21:00:05', '2025-05-05 21:00:05', NULL, NULL, 21);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(300, 'PROGRAM OLAHRAGA', '<p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">PROGRAM OLAHRAGA</span></font></font></p><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Futsal / Minsoc</span></font></font></p><ul><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Setiap karyawan diwajibkan untuk mengikuti kegiatan olahraga futsal / Minsoc1 minggu sekali, yang diadakan oleh pihak perusahaan.</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Wajib menggunakan celana panjang</span></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Wajib mengikuti aturan Futsal / Minsoc sesuai arahan dari PIC Program</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Karyawan yang tidak bisa hadir harus memberitahukan sebelumnya kepada ketua timnya.</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jika karyawan tidak hadir tanpa pemberitahuan sebelumnya atau dengan alasan yang tidak sesuai maka akan mempengaruhi penilaian diakhir tahun.</font></font></p></li></ul><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><br></p><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Lari</span></font></font></p><ul><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Setiap karyawan diwajibkan untuk lari 2x periode dalam 1 minggu</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Min. jarak tempuh dalam 1x periode ialah 4 km, dengan kecepatan ( pace ) min. 8</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jadwal lari Periode 1, hari Senin – Rabu, bila hari rabu belum maelaksanakan lari, maka diberikan toleransi dihari kamis pagi, atau saat jam istirahat.</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jadwal lari periode 2, hari Jum’at – Minggu</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Lari menggunakan aplikasi STRAVA.</span></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Data lari otomatis terekap disistemku</span></font></p></li></ul><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\"><br></span></font></font></p><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Timbang Badan</span></font></font></p><ul><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Kegiatan timbang badan dijadwalkan 1 bulan sekali</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Input data timbang badan ke sistemku</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Hasil timbang badan yang masuk kategori obesitas, akan masuk program penurunan berat badan</font></font></p></li></ul><p><font face=\"Arial, sans-serif\"><br></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Sepeda</span></font></font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan yang tinggal dalam jarak 1 hingga 7,5 kilometer dari kantor diwajibkan menggunakan sepeda untuk berangkat kerja.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Dalam satu minggu kerja (Senin sampai Sabtu), karyawan diminta menggunakan sepeda minimal 3 kali. Sisanya bebas.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika dalam seminggu karyawan tidak memenuhi penggunaan sepeda sebanyak 3 kali, maka akan dikenakan sanksi berupa iqob sepeda.&nbsp;</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan yang masuk dalam ketentuan ini wajib memiliki sepeda.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika belum memiliki sepeda, perusahaan menyediakan bantuan subsidi sebesar 50% dari harga sepeda.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Apabila karyawan berhenti bekerja, maka subsidi tersebut wajib dikembalikan. Pengembalian akan dilakukan melalui pemotongan dari hak karyawan yang masih tersisa.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Subsidi sebesar 50% wajib dikembalikan kepada perusahaan apabila karyawan mengundurkan diri atau diberhentikan sebelum masa kerja mencapai satu tahun. Namun, jika karyawan telah bekerja selama lebih dari satu tahun, maka subsidi 50% tersebut tidak perlu dikembalikan dan apabila selama bekerja tidak boleh dijual atau di gadai.<br></font></font><br></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\"><span style=\"font-weight: bolder;\">Penyesuaian program sepeda di pekan yang bertepatan dengan PHBN/ Tanggal Merah, ataupun cuti bagi SDM yang berkewajiban menjalankan Program :&nbsp;</span></span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Kondisi Pertama : Jika ada tanggal merah di pekan berjalan,&nbsp;</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">kewajiban sepeda berkurang sesuai tanggal merah di pekan tersebut</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">misal : Tanggal 1 -6, Tanggal 2 nya Tanggal merah, Maka kewajiban bersepeda hanya menjadi 2 kali</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">dan berlaku akumulatif,&nbsp;</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">(jika lebih dari 1 maka kewajiban bersepda berkurang sesuai banyakna tanggal merah dipekan berjalan)</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Kondisi Kedua : Jika Karyawan mengambil cuti dipekan berjalan</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Kewajiban sepeda berkurang sesuai banyakna cuti yang diambil dipekan berjalan</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">misal : Tanggal 1-6 , Ambil 1 hari cuti maka kewajiban bersepedannya berkurang 1x, dan berlaku akumulatif,</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">(jika cuti diambil lebih dari 1 hari maka kewajiban bersepeda berkurang sesuai banyaknya cuti yang diambil dipekan berjalan)</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Kondisi Ketiga Jika Karyawan Ambil cuti di pekan yang ada tanggal merahnya</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Kewajiban sepeda berkurang sesuai banyaknya cuti dan tanggal merah di pekan berjalan</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font style=\"box-sizing: inherit; font-size: 13.3333px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">dan berlaku akumulatif.</span></font></p></li></ul>', '', '2025-05-05 21:00:52', '2026-09-04 14:40:58', NULL, NULL, 21);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(301, 'PROGRAM ROHANI', '<p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">P</span><span style=\"font-weight: bolder;\">ROGRAM ROHANI</span></font></font></p><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">T</span><span style=\"font-weight: bolder;\">ilawah &amp; Tahsin</span></font></font></p><ul><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Setiap karyawan diwajibkan untuk mengikuti tilawah rutin melalui aplikasi yang telah ditetapkan, setiap hari minimal 1 halaman per hari,</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Data Rekapan tilawah otomatis terekap disistemku</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Setiap pagi dihari kerja sebelum briefing pagi, dilaksanakan tilawah bersama disetiap divisi. ( Bisa berubah sewaktu waktu )</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Untuk kegiatan Tahsin, karyawan &amp; freelance ( tetap ) akan dikelompokkan dan disesuaikan dengan kemampuan membaca Qurannya</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Program tahsin ( belajar mengaji ), berlaku untuk karyawan &amp; freelance tetap.</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Tahsin dijadwalkan setiap 1 minggu sekali.</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Tahsin dijadwalkan mulai pukul 07.30 - 09.00 WIB.( Conditional )</font></font></p></li></ul><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Kajian Rutin</span></font></font></p><ul><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Kajian rutin dilaksanakan 2 minggu sekali</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Pemateri, waktu &amp; lokasi kajian sudah ditentukan.</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">SDM luar kota bisa mengikuti secara online via link yang sudah disiapkan..</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Karyawan &amp; freelance tetap, absen melalui aplikasi yang telah ditentukan</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Kehadiran saat kajian, dapat mempengaruhi penilaian akhir tahun</font></font></p></li></ul><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Yaumian </span></font></font></font></span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Sholat 5 </span></font></font></font></span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">W</span></font></font></font></span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">aktu </span></font></font></font></span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">B</span></font></font></font></span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">erjamaah</span></font></font></font></span></p><ul><li><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">SDM mengisi via sistemku, </font></font><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">maksimal ( H+2 ), karena akan terkunci otomatis</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Leader setiap divisi </font></font><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">akan</font></font><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"> mengingatkan timnya yang belum mengisi yaumian</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Bila telat mengisi yaumian disistemku, maka tim HR akan merekap sesuai yang terisi, untuk keperluan data performance akhir tahun.</font></font></p></li></ul><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\"><br></span></font></font></font></span></p><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">I</span></font></font></font></span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">tikaf Bulan Ramadhan</span></font></font></font></span></p><ul><li><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Karyawan &amp; Freelance mengikuti kegiatan Itikaf dimesjid yang telah ditentukan.</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Selama mengikuti kegiatan itikaf, karyawan &amp; Freelance harus mengikuti aturan yang telah ditentukan oleh panitia Itikaf,&nbsp;</font></font></p></li></ul><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\"><br></span></font></font></p><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Baca Surat Alkahf</span></font></font></p><ul><li><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Dibaca setiap hari Jum’at ( diusahakan baca full sampai akhir surat )</font></font></li></ul>', '', '2025-05-05 21:01:42', '2026-09-04 14:58:11', NULL, NULL, 21);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(302, 'TEGURAN DAN SURAT PERINGATAN', '<p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 1rem; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">SANKSI</span></font></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Teguran Lisan</span></font></font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika melanggar aturan yang telah ditetapkan, maka akan diberikan teguran lisan terlebih dahulu, dan sanksi akan meningkat bila masih melakukan pelanggaran kembali.</font></font></font></p><ul style=\"box-sizing: inherit;\"></ul><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">SP 1</span></font></font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika karyawan melakukan pelanggaran kembali secara berulang, setelah diberikan teguran lisan, maka akan mendapatkan SP 1 dengan ketentuan sbb :</font></font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; line-height: 16px;\"><span style=\"box-sizing: inherit; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Mengisi&nbsp;</font></font></font></span><em style=\"box-sizing: inherit;\"><span style=\"box-sizing: inherit; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-style: normal;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Form SP 1</span></span></font></font></font></span></em></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Sanki yang diterima :</font></font></font></p><ul style=\"box-sizing: inherit;\"><li style=\"box-sizing: inherit;\"><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Segala bentuk promosi dan kenaikan gaji akan ditangguhkan</font></font></font></p></li><li style=\"box-sizing: inherit;\"><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">mengurangi penilaian bonus akhir tahun</font></font></font></p></li><li style=\"box-sizing: inherit;\"><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Peringatan ini akan dihapuskan apabila selama 1 (satu) bulan yang bersangkutan tidak melakukan pelanggaran</font></font></font></p></li><li style=\"box-sizing: inherit;\"><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Bila dalam masa hukuman melakukan pelanggaran kembali, maka statusnya meningkat menjadi SP 2</font></font></font></p></li></ul><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><br style=\"box-sizing: inherit;\"></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">SP 2</span></font></font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika karyawan melakukan pelanggaran kembali setelah mendapatkan SP 1 maka akan mendapatkan SP 2 dengan ketentuan sbb :</font></font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; line-height: 16px;\"><span style=\"box-sizing: inherit; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Mengisi</font></font></font></span><span style=\"box-sizing: inherit; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"></font></font></font></span><em style=\"box-sizing: inherit;\"><span style=\"box-sizing: inherit; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-style: normal;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Form SP 2</span></span></font></font></font></span></em></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Sanki yang diterima :</font></font></font></p><ul style=\"box-sizing: inherit;\"><li style=\"box-sizing: inherit;\"><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Segala bentuk promosi dan kenaikan gaji akan ditangguhkan</font></font></font></p></li><li style=\"box-sizing: inherit;\"><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">mengurangi penilaian bonus akhir tahun</font></font></font></p></li><li style=\"box-sizing: inherit;\"><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Peringatan ini akan dihapuskan apabila selama 2 (dua) bulan yang bersangkutan tidak melakukan pelanggaran</font></font></font></p></li><li style=\"box-sizing: inherit;\"><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Bila dalam masa hukuman melakukan pelanggaran kembali, maka statusnya meningkat menjadi SP 3</font></font></font></p></li></ul><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><br style=\"box-sizing: inherit;\"></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">SP 3</span></font></font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika Karyawan yang mendapatkan SP 3, silahkan mengundurkan diri ( resign ).</font></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><br style=\"box-sizing: inherit; text-align: justify; background-color: rgb(233, 237, 242);\"></p>', '', '2025-05-05 21:02:56', '2025-05-05 21:02:56', NULL, NULL, 20);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(303, 'TUNJANGAN KARYAWAN', '<ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px; background: transparent;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">TUNJANGAN KARYAWAN</span></font></font></p></ul><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Tunjangan makan</span></font></font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Makan siang karyawan sudah disediakan oleh perusahan untuk hari Senin – Jum’at.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Khusus untuk hari sabtu makan siang diganti dengan uang cash Rp.20.000,-</font></font></p></li></ul><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><br style=\"box-sizing: inherit;\"></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Tunjangan Kesehatan</span></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Setiap karyawan berhak untuk mendapatkan tunjangan kesehatan dengan ketentuan sbb :</font></font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan dengan status&nbsp;<span style=\"box-sizing: inherit; font-weight: bolder;\">sudah menikah</span>&nbsp;mendapatkan rp. 900.000,- pertahun</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan dengan status&nbsp;<span style=\"box-sizing: inherit; font-weight: bolder;\">belum menikah</span>&nbsp;mendapatkan rp. 600.000,- pertahun</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Masa kerja kurang dari 1 tahun nilai tunjangannya sbb :</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><u style=\"box-sizing: inherit;\">Masa kerja (bulan)</u>&nbsp;x nilai tunjangan kesehatan</font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;12</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Tunjangan kesehatan tidak bisa digunakan lagi bila sudah mencapai limit</font></font></p></li></ul><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Sistem penggunaannya adalah sistem reimburst, dengan menyerahkan bukti-bukti biaya pengobatan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Tunjangan kesehatan bisa digunakan oleh karyawan yang bersangkutan dan keluarganya.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika sampai akhir tahun masih ada sisa yang tidak digunakan maka akan diberikan uang tunai senilai uang tunjangan yang masih tersisa</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Pembayaran uang tunjangan kesehatan yang tersisa dilakukan paling lambat di bulan pertama tahun berikutnya</font></font></p></li></ul><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\"><br style=\"box-sizing: inherit;\"></span></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Tunjangan Kecelakan Kerja</span></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Setiap karyawan yang mengalami kecelakan selama melakukan pekerjaan maka akan mendapatkan tunjangan kecelakan kerja, kecuali kecelakaan yang diakibatkan oleh kelalaian karyawan itu sendiri.</font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Yang dimaksud dengan kecelakaan kerja adalah kecelakaan yang menimpa seorang pegawai pada saat:</font></font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan meninggalkan rumah/tempat tinggalnya untuk menuju tempat kerja dengan melalui jalan yang biasa dilaluinya.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan bekerja atau berada ditempat kerja.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan dalam perjalanan pulang ke rumah atau tempat tinggalnya dengan melalui jalan yang biasa dilaluinya.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Tunjangan kecelakan kerja berupa biaya pengobatan ditanggung oleh perusahaan dengan nilai yang akan ditentukan kemudian oleh pihak manajemen perusahaan sesuai dengan kondisi yang ada.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Sistem penggunaannya adalah sistem reimburst dengan menyerahkan bukti-bukti biaya pengobatan</font></font></p></li></ul><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\"><br style=\"box-sizing: inherit;\"></span></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Tunjangan Hari Raya</span></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Setiap karyawan berhak untuk mendapatkan tunjangan hari raya dengan ketentuan sbb :</font></font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Masa kerja 1 tahun atau lebih mendapatkan 100% dari nilai perhitungan THR</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Masa kerja kurang dari 1 tahun nilai tunjangannya sbb :</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><u style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Masa kerja(bulan)&nbsp;</font></font></u><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">x nilai perhitungan THR</font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;12</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Nilai perhitungan THR akan ditentukan kemudian sesuai keputusan pihak manajemen dan bisa berubah-rubah sesuai dengan kondisi yang ada</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Pembayaran THR dilakukan beberapa hari sebelum hari raya idul fitri</font></font></p></li></ul><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><br style=\"box-sizing: inherit;\"></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Tunjangan Kehadiran</span></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Setiap karyawan berhak untuk mendapatkan tunjangan kehadiran dengan ketentuan sbb:</font></font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan akan mendapatkan tunjangan kehadiran sebesar Rp.175.000 perbulan, bila dalam 1 bulan full absen tanpa ada keterlambatan.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika karyawan terlambat atau tidak absen 1x, maka nilai tunjangan akan berkurang sebesar Rp. 75.000</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika karyawan terlambat atau tidak absen 2x, maka tunjangan kehadirannya akan hangus.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Keterlambatan akan mempengaruhi penilaian diakhir tahun.</font></font></p></li></ul><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><br style=\"box-sizing: inherit;\"></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Bonus Tahunan</span></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Setiap karyawan berhak untuk mendapatkan bonus tahunan yang nominalnya sesuai dengan keputusan manajemen perusahaan berdasarkan parameter sbb :</font></font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Kondisi keuangan perusahaan diakhir tahun, Lama kerja, Jabatan, Prestasi kerja ( mencakup performance kinerja karyawan ).</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Pembayaran bonus tahunan direalisasikan setelah data valid</font></font></p></li></ul>', '', '2025-05-05 21:15:36', '2025-05-05 21:15:36', NULL, NULL, 24);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(304, 'KASBON', '<p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">KASBON</span></font></font></p><ul style=\"box-sizing: inherit;\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Setiap karyawan diberikan limit untuk setiap pengajuan kasbon, yaitu 90% dari total gaji ( diluar perhitungan bonus &amp; lemburan ),</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Nilai pengajuan kasbon harus disetujui oleh atasannya terlebih dahulu.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan tidak bisa mengajukan kasbon, apabila karyawan tersebut masih mempunyai kasbon yang belum selesai / belum dilunasi.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">karyawan yang akan mengajukan kasbon mengisi form yang sudah disediakan, dan disetujui oleh atasannya.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Pengembalian kasbon bisa dengan cara dicicil, yaitu maksimal dalam jangka waktu 3 bulan, dengan besar minimum pengembalian perbulannya ialah 30% dari total gaji.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Apabila pengajuan kasbon dengan nilai kasbonnya dibawah 30% dari total nilai gaji, maka kasbonnya akan langsung dipotongkan semua dipenggajian bulan berikutnya.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Apabila karyawan sudah melunasi kasbonnya, maka baru bisa mengajukan kasbon lagi, dalam rentang waktu 1 bulan kedepan setelah pelunasan.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Data pengajuan yang sudah diajukan, akan dikroscek serta divalidasi oleh bag. Finance</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Bila data sudah valid &amp; disetujui, maka akan direalisasikan maksimal 2 x 24 jam ( Hari kerja )</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Apabila ada karyawan berhenti/ keluar kerja, tetapi masih memiiki kasbon, maka harus diselesaikan/ dilunasi.&nbsp;</font></font></p></li></ul>', '', '2025-05-05 21:16:45', '2025-05-05 21:16:45', NULL, NULL, 24);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(305, 'LEMBUR', '<ul style=\"box-sizing: inherit;\"><ul style=\"box-sizing: inherit;\"><ul><ul><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px; background: transparent;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">LEMBUR</span></font></font></p></ul><ul><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Lembur berlaku, jika karyawan masih bekerja diluar dari waktu kerja yang telah ditentukan.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Lembur dilakukan atas permintaan atasannya langsung.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jika lembur dilakukan 3 jam atau lebih maka ada tambahan uang makan lembur Rp.10.000,-, tapi jika lemburnya harus sampai keluar kota maka akan disesuaikan dengan kondisi yang ada</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Ketentuan perhitungan uang lembur :</font></font></p><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><em>Freelance Rp. 7</em><em>,5</em><em>00</em><em>&nbsp;x jumlah jam lembur&nbsp;</em></font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><em style=\"font-size: 10pt; font-family: Arial, sans-serif;\">Karyawan Rp. 9,000 x jumlah jam lembur</em></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Untuk lembur silahkan&nbsp;mengisi pengajuan Lembur diaplikasi&nbsp;<span style=\"font-weight: bolder;\">Web Sistemku,</span>&nbsp;dan&nbsp;Atasannya mengisi data lembur bawahannya di link SS yang sudah disediakan.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Data Validasi akan direkonsil oleh tim HR</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Pembayaran uang lembur, diberikan pada saat pembayaran gaji yang bersangkutan ( disatukan ).</font></font></p></li></ul></ul></ul></ul>', '', '2025-05-05 21:17:18', '2026-06-02 16:50:12', NULL, NULL, 24),
(306, 'CUTI', '<p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">CUTI</span></font></font></p><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Cuti regular</span></font></font></p><ul><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Cuti diberikan kepada karyawan yang telah melewati masa percobaan kerja selama 3 bulan</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Cuti regular diberikan pertahun sebanyak 12 kali.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Karyawan yang belum genap 1 tahun bekerja maka jumlah cuti yg didapatkan adalah : 1 x ( jumlah bulan bekerja - masa percobaan 3 bulan ).</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Pengajuan cuti maksimal 1 hari sebelum hari cuti, dengan mengisi Form Pengajuan Cuti diaplikasi&nbsp;<span style=\"font-weight: bolder;\">Web Sistemku</span></font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Cuti dadakan tidak diperkenankan, misal hari H tidak masuk kerja kemudian yang bersangkutan ingin dimasukkan cuti, itu tidak bisa dilakukan, akan dimasukkan kategori ijin biasa.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Pengajuan cuti harus diketahui, dan disetujui atasannya langsung.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Pengambilan cuti dalam 1 bulan hanya bisa maksimal 3 hari</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jika sampai akhir tahun masih ada jatah cuti yang tidak diambil maka ada penggantian dalam bentuk kompensasi uang.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Uang kompensasi sisa cuti, akan diberikan pada bulan pertama ditahun berikutnya</font></font></p></li></ul><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Cuti khusus</span></font></font></p><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Setiap karyawan berhak mendapatkan cuti khusus selain cuti regular diatas, yaitu :</font></font></p><ul><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Cuti anggota keluarga meninggal (ayah/ibu, adik/kakak, istri/suami, anak) : 1 hari</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Cuti istri melahirkan : 1 hari</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Cuti hamil / melahirkan : jumlah cuti disesuaikan dengan keputusan manajemen perusahaan. Selama masa cuti tersebut, karyawan tetap mendapatkan gaji pokok.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Cuti Menikah : 1 hari</font></font></p></li></ul><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><br></p><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Cuti Tambahan</span></font></font></p><ul><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Karyawan dapat mengajukan cuti tambahan, bila saldo cutinya sudah habis ditahun berjalan. Dengan catatan,<em>&nbsp;cuti tambahan berlaku/ dapat diajukan bila kondisi sangat mendesak, dan tidak dapat ditangguhkan</em>.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Karyawan yang mengajukan cuti tambahan, harus disetujui oleh atasannya masing-masing. Dan dipastikan saat cuti, pekerjaan yang bersangkutan sudah ada yang backup untuk handle pekerjaannya.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Karyawan yang mengajukan&nbsp;<span style=\"font-weight: bolder;\">cuti tambahan</span>, maka akan&nbsp;<span style=\"font-weight: bolder;\">mengurangi saldo cutinya ditahun berikutnya</span>.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Karyawan yang mengajukan cuti tambahan, dapat melalui aplikasi&nbsp;<span style=\"font-weight: bolder;\">Web Sisitemku</span>. Silahkan masuk ke aplikasi Web Sistemku, klik menu&nbsp;<span style=\"font-weight: bolder;\">IJIN/CUTI</span>, isi kolom tipe pilih&nbsp;<span style=\"font-weight: bolder;\">IJIN</span>, lalu dikolom keterangan isi :&nbsp;<span style=\"font-weight: bolder;\">(Cuti tambahan),&nbsp;</span><span style=\"font-weight: bolder;\">kemudian</span><span style=\"font-weight: bolder;\">&nbsp;sertakan alasannya.</span></font></font></p></li></ul>', '', '2025-05-05 21:17:53', '2026-06-02 16:45:48', NULL, NULL, 24),
(307, 'IJIN', '<p align=\"justify\" style=\"margin-bottom: 0in; font-size: 16px; background-color: oklab(0.98 0 0 / 0.5); line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">IZIN</span></font></font></p><p align=\"justify\" style=\"margin-bottom: 0in; font-size: 16px; background-color: oklab(0.98 0 0 / 0.5); line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Izin tidak masuk kerja</span></font></font></p><ul style=\"font-size: 16px; background-color: oklab(0.98 0 0 / 0.5);\"><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jika ijin tidak masuk kerja, maka yang bersangkutan mengisi permohonan ijin tidak masuk kerja yang ada diaplikasi web sistemku.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Yang bersangkutan memberitahukan juga ke atasannya langsung ( bisa via tlp atau chat )</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Bila yang bersangkutan tidak ada kabar berita, maka dianggap mangkir. Akan mempengaruhi penilaian diakhir tahun, dan performance nya akan dievaluasi kembali.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Bila mangkir lebih dari 1x, maka akan dikenakan sanksi teguran SP 1, jika sudah mendapat SP 1, tetapi dilakukan kembali maka sanksinya meningkat menjadi SP 2, dan jika berulang kembali maka sanksi naik menjadi SP 3.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Ijin tidak masuk kerja berbeda dengan cuti, sifatnya mutlak, dan statusnya tidak bisa bertukar dari ijin menjadi cuti dan sebaliknya dari cuti menjadi ijin.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Izin tidak masuk kerja karena alasan sakit, harus menyertakan surat keterangan sakit dari dokter dan kwintansi biaya berobat untuk claim penggantian biaya berobat tersebut.&nbsp;</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Bila tidak menyertakan surat dokter dan kwitansi biaya berobat, maka tunjangan kesehatannya tidak bisa digunakan untuk claim biaya berobat tersebut.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jika ijin sakit tidak menyertakana surat sakit, maka akan dianggap ijin biasa saja, bukan termasuk kategori sakit.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jika yang bersangkutan sakit selama 3 hari belum bisa masuk kerja, maka atasan serta rekan kerja akan menjenguk yang bersangkutan.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Ijin sering tidak masuk kerja, maka akan mempengaruhi peniaian diakhir tahun</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Ijin maksimal 3x dalam 1 bulan, bila melebihi batas ijin yang bersangkutan akan dievaluasi dan diberikan teguran secara bertahap.</font></font></p></li></ul><p align=\"justify\" style=\"margin-bottom: 0in; font-size: 16px; background-color: oklab(0.98 0 0 / 0.5); line-height: 16px;\"><br></p><p align=\"justify\" style=\"margin-bottom: 0in; font-size: 16px; background-color: oklab(0.98 0 0 / 0.5); line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Izin meninggalkan pekerjaan (IMP)</span></font></font></p><ul style=\"font-size: 16px; background-color: oklab(0.98 0 0 / 0.5);\"><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jika akan meninggalkan pekerjaan sementara waktu, maka harus memberitahukan ke atasannya langsung, dan harus diijinkan oleh atasannya.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">IMP bisa dilakukan jika karyawan telah hadir bekerja terlebih dahulu &amp; Absen diweb sistemku saat jam masuk pagi hari.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Tidak tercatat IMP bila dibawah batas toleransi yaitu 1 jam, bila meninggalkan pekerjaan lebih dari 1 jam, maka dicatat IMP.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"></font></font></p><ul><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">IMP harus mengisi form pengajuan diaplikasi web sistemku ( masuk kategori ijin, dan dikolom keterangan tulis IMP ).</font></font></p></li></ul></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jika sering IMP, akan mempengaruhi penilaian akhir tahun, dan performance yang bersangkutan akan dievaluasi.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">IMP hanya bisa dilakukan untuk kondisi yang bersifat<span style=\"font-weight: bolder;\">&nbsp;urgent</span>.</font></font></p></li></ul>', '', '2025-05-05 21:18:31', '2026-06-02 16:39:07', NULL, NULL, 24);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(308, 'ABSENSI', '<p style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">ABSENSI</span></font></font></p><table class=\"table table-zebra w-full text-base [&amp;_a]:text-blue-600\" style=\"width: 1322.47px; border-spacing: 0px; border-radius: 8px; font-size: medium; line-height: 1.5;\"><tbody><tr class=\"bg-base-200/50\" style=\"background-color: oklab(0.98 0 0 / 0.5);\"><td colspan=\"2\" class=\"py-3\" style=\"padding-block: 12px;\"><p style=\"font-size: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Absensi menggunakan&nbsp;</font></font><span style=\"font-weight: bolder;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><em>sistem digital</em></font></font></span><span style=\"font-weight: bolder;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">&nbsp;&nbsp;</span></font></font></span><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">dengan Aplikasi&nbsp;</font></font><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Web Sistemku</span></font></font><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">&nbsp;sebagai alat bantu absensi</font></font></p><ol type=\"A\" style=\"font-size: 16px;\"><li><p style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Absensi dilakukan setiap hari kerja pada saat jam datang, dan dilokasi yang sudah ditetapkan.</font></font></p></li><li><p style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Absen diaplikasi&nbsp;<span style=\"font-weight: bolder;\">web Sistemku</span>&nbsp;menggunakan scan verifikasi wajah</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Bila ada Karyawan &amp; Freelance, tidak melakukan absen diaplikasi web sistemku atas kelalaiannya sendiri ( diluar kendala teknis ). Tetapi yang bersangkutan hadir untuk bekerja diwaktu tersebut, maka;</font></font></p><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 0.2in; background: transparent; break-before: auto;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Untuk&nbsp;<span style=\"font-weight: bolder;\">F</span><span style=\"font-weight: bolder;\">reelance,</span><span style=\"font-weight: bolder;\">&nbsp;masuk kategori&nbsp;</span><span style=\"font-weight: bolder;\">ijin ( mangkir )</span>. Bila dilakukan kembali dalam periode dibulan yang sama ( lebih dari 3x ), maka akan kena sanksi secara bertahap, mulai dari teguran lisan,jika berulang dibulan berikutnya akan dikenakan sanksi tegas berupa&nbsp; teguran tertulis SP 1, dan bila sudah mendapat SP 1, tetapi tetap dilakukan kembali maka sanksi teguran naik jadi SP 2, dan bila tidak ada perubahan sanksi meningkat menjadi SP 3 ( diresignkan secara sepihak ).</font></font></p><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Untuk&nbsp;<span style=\"font-weight: bolder;\">Karyawan,&nbsp;</span><span style=\"font-weight: bolder;\">masuk kategori ijin ( mangkir ).&nbsp;</span>karyawan yang tidak absen di aplikasi web sistemku dalam periode bulan yang sama lebih dari 2x, maka uang kehadirannya hangus ( dianggap terlambat absen ), Jika dalam periode bulan yg sama ( lebih dari 3x ), maka akan kena sanksi teguran lisan, jika dibulan berikutnya berulang maka dikenakan sanksi tertulis SP 1, dan bila sudah mendapat SP 1, tetap dilakukan kembali maka sanksi teguran naik jadi SP 2, dan bila tidak ada perubahan sanksi meningkat menjadi SP 3 ( diresignkan secara sepihak ).</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Bila ada Karyawan &amp; Freelance, tidak melakukan absen diaplikasi web sistemku dikarenakan&nbsp;<span style=\"font-weight: bolder;\">kendala teknis</span>, seperti error aplikasi, HP error, dsb, bisa membuat surat rekomendasi yang disetujui atasannya langsung, dan dianggap&nbsp;<span style=\"font-weight: bolder;\">hadir</span>.</font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span lang=\"id-ID\">Akumulasi sanksi yang didapat&nbsp;</span><span lang=\"id-ID\">akan mempengaruhi penilaian performa&nbsp;</span><span lang=\"id-ID\">yang bersangkutan&nbsp;</span><span lang=\"id-ID\">&nbsp;</span><span lang=\"id-ID\">di</span><span lang=\"id-ID\">akhir tahun.</span></font></font></p></li><li><p align=\"justify\" style=\"margin-bottom: 0in; line-height: 0.2in;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span lang=\"id-ID\">Untuk absen freelance harian, akan dipantau oleh atasannya langsung. Bila yang bersangkutan sering terlambat, disarankan&nbsp;</span><span lang=\"id-ID\">untuk yang bersangkutan&nbsp;</span><span lang=\"id-ID\">tidak&nbsp;</span><span lang=\"id-ID\">usah&nbsp;</span><span lang=\"id-ID\">dipanggil kerja lagi.</span></font></font></p></li></ol></td></tr></tbody></table>', '', '2025-05-05 21:19:03', '2026-06-02 16:31:56', NULL, NULL, 24);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(309, 'HARI &amp;JAM KERJA', '<p style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Hari Kerja</span></font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Hari kerja dalam 1 minggu 6 hari (senin – sabtu)</font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><br style=\"box-sizing: inherit;\"></p><p style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Jam Kerja</span></font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Senin – Jum’at : pkl.08.30 – 17.00 WIB</font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Sabtu : pkl.08.00 – 12.00 WIB</font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Istirahat 1 jam mulai pkl.12.00 – 13.00 WIB</font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika karyawan masih bekerja diluar waktu kerja yang telah ditentukan dan atas permintaan atasannya langsung, maka kelebihan jam kerja tersebut dihitung sebagai lembur.</font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><span style=\"box-sizing: inherit; font-weight: bolder;\"><br style=\"box-sizing: inherit;\"></span></p><p style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Libur Kerja</span></font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Hari ahad dan hari libur nasional</font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Libur hari raya idul fitri ditentukan kemudian disesuaikan dengan kondisi yang ada</font></font></p>', '', '2025-05-05 21:19:27', '2025-05-05 21:19:27', NULL, NULL, 24);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(310, 'PROGRAM ROHANI', '<p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">P</span><span style=\"font-weight: bolder;\">ROGRAM ROHANI</span></font></font></p><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">T</span><span style=\"font-weight: bolder;\">ilawah &amp; Tahsin</span></font></font></p><ul><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Setiap karyawan diwajibkan untuk mengikuti tilawah rutin melalui aplikasi yang telah ditetapkan, setiap hari minimal 1 halaman per hari,</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Data Rekapan tilawah otomatis terekap disistemku</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Setiap pagi dihari kerja sebelum briefing pagi, dilaksanakan tilawah bersama disetiap divisi. ( Bisa berubah sewaktu waktu )</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Untuk kegiatan Tahsin, karyawan &amp; freelance ( tetap ) akan dikelompokkan dan disesuaikan dengan kemampuan membaca Qurannya</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Program tahsin ( belajar mengaji ), berlaku untuk karyawan &amp; freelance tetap.</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Tahsin dijadwalkan setiap 1 minggu sekali.</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Tahsin dijadwalkan mulai pukul 07.30 - 09.00 WIB.( Conditional )</font></font></p></li></ul><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Kajian Rutin</span></font></font></p><ul><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Kajian rutin dilaksanakan 2 minggu sekali</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Pemateri, waktu &amp; lokasi kajian sudah ditentukan.</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">SDM luar kota bisa mengikuti secara online via link yang sudah disiapkan..</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Karyawan &amp; freelance tetap, absen melalui aplikasi yang telah ditentukan</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Kehadiran saat kajian, dapat mempengaruhi penilaian akhir tahun</font></font></p></li></ul><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Yaumian </span></font></font></font></span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Sholat 5 </span></font></font></font></span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">W</span></font></font></font></span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">aktu </span></font></font></font></span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">B</span></font></font></font></span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">erjamaah</span></font></font></font></span></p><ul><li><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">SDM mengisi via sistemku, </font></font><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">maksimal ( H+2 ), karena akan terkunci otomatis</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Leader setiap divisi </font></font><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">akan</font></font><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"> mengingatkan timnya yang belum mengisi yaumian</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Bila telat mengisi yaumian disistemku, maka tim HR akan merekap sesuai yang terisi, untuk keperluan data performance akhir tahun.</font></font></p></li></ul><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\"><br></span></font></font></font></span></p><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">I</span></font></font></font></span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">tikaf Bulan Ramadhan</span></font></font></font></span></p><ul><li><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Karyawan &amp; Freelance mengikuti kegiatan Itikaf dimesjid yang telah ditentukan.</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Selama mengikuti kegiatan itikaf, karyawan &amp; Freelance harus mengikuti aturan yang telah ditentukan oleh panitia Itikaf,&nbsp;</font></font></p></li></ul><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\"><br></span></font></font></p><p align=\"justify\" style=\"margin: 0px 0px 0.02in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Baca Surat Alkahf</span></font></font></p><ul><li><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Dibaca setiap hari Jum’at ( diusahakan baca full sampai akhir surat )</font></font></li></ul>', '', '2025-05-05 21:20:18', '2026-09-04 14:57:58', NULL, NULL, 25),
(311, 'PROGRAM OLAHRAGA', '<p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">PROGRAM OLAHRAGA</span></font></font></p><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Futsal / Minsoc</span></font></font></p><ul><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Setiap karyawan diwajibkan untuk mengikuti kegiatan olahraga futsal / Minsoc1 minggu sekali, yang diadakan oleh pihak perusahaan.</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Wajib menggunakan celana panjang</span></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Wajib mengikuti aturan Futsal / Minsoc sesuai arahan dari PIC Program</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Karyawan yang tidak bisa hadir harus memberitahukan sebelumnya kepada ketua timnya.</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jika karyawan tidak hadir tanpa pemberitahuan sebelumnya atau dengan alasan yang tidak sesuai maka akan mempengaruhi penilaian diakhir tahun.</font></font></p></li></ul><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><br></p><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Lari</span></font></font></p><ul><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Setiap karyawan diwajibkan untuk lari 2x periode dalam 1 minggu</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Min. jarak tempuh dalam 1x periode ialah 4 km, dengan kecepatan ( pace ) min. 8</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jadwal lari Periode 1, hari Senin – Rabu, bila hari rabu belum maelaksanakan lari, maka diberikan toleransi dihari kamis pagi, atau saat jam istirahat.</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Jadwal lari periode 2, hari Jum’at – Minggu</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Lari menggunakan aplikasi STRAVA.</span></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Data lari otomatis terekap disistemku</span></font></p></li></ul><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\"><br></span></font></font></p><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\"><span style=\"font-weight: bolder;\">Timbang Badan</span></font></font></p><ul><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Kegiatan timbang badan dijadwalkan 1 bulan sekali</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Input data timbang badan ke sistemku</font></font></p></li><li><p align=\"justify\" style=\"margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><font style=\"font-size: 10pt;\">Hasil timbang badan yang masuk kategori obesitas, akan masuk program penurunan berat badan</font></font></p></li></ul><p><font face=\"Arial, sans-serif\"><br></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Sepeda</span></font></font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan yang tinggal dalam jarak 1 hingga 7,5 kilometer dari kantor diwajibkan menggunakan sepeda untuk berangkat kerja.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Dalam satu minggu kerja (Senin sampai Sabtu), karyawan diminta menggunakan sepeda minimal 3 kali. Sisanya bebas.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika dalam seminggu karyawan tidak memenuhi penggunaan sepeda sebanyak 3 kali, maka akan dikenakan sanksi berupa iqob sepeda.&nbsp;</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan yang masuk dalam ketentuan ini wajib memiliki sepeda.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika belum memiliki sepeda, perusahaan menyediakan bantuan subsidi sebesar 50% dari harga sepeda.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Apabila karyawan berhenti bekerja, maka subsidi tersebut wajib dikembalikan. Pengembalian akan dilakukan melalui pemotongan dari hak karyawan yang masih tersisa.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Subsidi sebesar 50% wajib dikembalikan kepada perusahaan apabila karyawan mengundurkan diri atau diberhentikan sebelum masa kerja mencapai satu tahun. Namun, jika karyawan telah bekerja selama lebih dari satu tahun, maka subsidi 50% tersebut tidak perlu dikembalikan dan apabila selama bekerja tidak boleh dijual atau di gadai.<br></font></font><br></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\"><span style=\"font-weight: bolder;\">Penyesuaian program sepeda di pekan yang bertepatan dengan PHBN/ Tanggal Merah, ataupun cuti bagi SDM yang berkewajiban menjalankan Program :&nbsp;</span></span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Kondisi Pertama : Jika ada tanggal merah di pekan berjalan,&nbsp;</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">kewajiban sepeda berkurang sesuai tanggal merah di pekan tersebut</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">misal : Tanggal 1 -6, Tanggal 2 nya Tanggal merah, Maka kewajiban bersepeda hanya menjadi 2 kali</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">dan berlaku akumulatif,&nbsp;</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">(jika lebih dari 1 maka kewajiban bersepda berkurang sesuai banyakna tanggal merah dipekan berjalan)</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Kondisi Kedua : Jika Karyawan mengambil cuti dipekan berjalan</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Kewajiban sepeda berkurang sesuai banyakna cuti yang diambil dipekan berjalan</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">misal : Tanggal 1-6 , Ambil 1 hari cuti maka kewajiban bersepedannya berkurang 1x, dan berlaku akumulatif,</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">(jika cuti diambil lebih dari 1 hari maka kewajiban bersepeda berkurang sesuai banyaknya cuti yang diambil dipekan berjalan)</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Kondisi Ketiga Jika Karyawan Ambil cuti di pekan yang ada tanggal merahnya</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">Kewajiban sepeda berkurang sesuai banyaknya cuti dan tanggal merah di pekan berjalan</span></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font style=\"box-sizing: inherit; font-size: 13.3333px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin: 0px 0px 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\"><span style=\"font-size: 13.3333px;\">dan berlaku akumulatif.</span></font></p></li></ul>', '', '2025-05-05 21:20:43', '2026-09-04 14:40:15', NULL, NULL, 25);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(312, 'PROGRAM SOSIAL', '<p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">PROGRAM SOSIAL</span></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Donor Darah</span></font></font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Setiap karyawan diwajibkan untuk mengikuti kegiatan Donor Darah yang diadakan oleh pihak perusahaan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Donor darah dilakukan rutin minimal 2 bulan sekali.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Waktu, dan tempat kegiatan ditentukan oleh pihak perusahaan</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Karyawan yang tidak bisa hadir / tidak lolos donor darah maka harus mencoba lagi donor darah dicabang PMI terdekat.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Batas Waktu percobaan ulang donor, adalah 7 hari dari waktu kegiatan donor darah massal</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika dipercobaan donor ulang tetap tidak berhasil dan batas waktunya sudah habis, maka tidak perlu mencoba donor lagi</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">kegiatan donor darah dapat mempengaruhi penilaian diakhir tahun.</font></font></p></li></ul><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><br style=\"box-sizing: inherit;\"></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; background-color: rgb(233, 237, 242); line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Bakti Sosial</span></font></font></p><ul style=\"box-sizing: inherit; background-color: rgb(233, 237, 242);\"><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Kegiatan Jumsih, kegiatan bakti sosial yang dlaksanakan setiap hari jumat pagi dilingkungan sekitar kantor.</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Peserta jumsih terdiri dari karyawan &amp; freelance ( opsional )</font></font></p></li><li style=\"box-sizing: inherit;\"><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Peserta jumsih akan dikelompokkan, dan ditentukan lokasi pelaksanaannya.</font></font></p></li></ul>', '', '2025-05-05 21:21:54', '2025-05-05 21:21:54', NULL, NULL, 25);
INSERT INTO `data_sops` (`id`, `judul`, `isi`, `bagian`, `created_at`, `updated_at`, `company_id`, `global`, `kategori_id`) VALUES
(313, 'TEGURAN DAN SURAT PERINGATAN', '<p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 1rem; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">SANKSI</span></font></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Teguran Lisan</span></font></font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika melanggar aturan yang telah ditetapkan, maka akan diberikan teguran lisan terlebih dahulu, dan sanksi akan meningkat bila masih melakukan pelanggaran kembali.</font></font></font></p><ul style=\"box-sizing: inherit;\"></ul><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">SP 1</span></font></font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika karyawan melakukan pelanggaran kembali secara berulang, setelah diberikan teguran lisan, maka akan mendapatkan SP 1 dengan ketentuan sbb :</font></font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; line-height: 16px;\"><span style=\"box-sizing: inherit; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Mengisi&nbsp;</font></font></font></span><em style=\"box-sizing: inherit;\"><span style=\"box-sizing: inherit; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-style: normal;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Form SP 1</span></span></font></font></font></span></em></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Sanki yang diterima :</font></font></font></p><ul style=\"box-sizing: inherit;\"><li style=\"box-sizing: inherit;\"><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Segala bentuk promosi dan kenaikan gaji akan ditangguhkan</font></font></font></p></li><li style=\"box-sizing: inherit;\"><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">mengurangi penilaian bonus akhir tahun</font></font></font></p></li><li style=\"box-sizing: inherit;\"><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Peringatan ini akan dihapuskan apabila selama 1 (satu) bulan yang bersangkutan tidak melakukan pelanggaran</font></font></font></p></li><li style=\"box-sizing: inherit;\"><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Bila dalam masa hukuman melakukan pelanggaran kembali, maka statusnya meningkat menjadi SP 2</font></font></font></p></li></ul><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><br style=\"box-sizing: inherit;\"></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">SP 2</span></font></font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika karyawan melakukan pelanggaran kembali setelah mendapatkan SP 1 maka akan mendapatkan SP 2 dengan ketentuan sbb :</font></font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; line-height: 16px;\"><span style=\"box-sizing: inherit; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Mengisi</font></font></font></span><span style=\"box-sizing: inherit; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"></font></font></font></span><em style=\"box-sizing: inherit;\"><span style=\"box-sizing: inherit; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-style: normal;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">Form SP 2</span></span></font></font></font></span></em></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Sanki yang diterima :</font></font></font></p><ul style=\"box-sizing: inherit;\"><li style=\"box-sizing: inherit;\"><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Segala bentuk promosi dan kenaikan gaji akan ditangguhkan</font></font></font></p></li><li style=\"box-sizing: inherit;\"><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">mengurangi penilaian bonus akhir tahun</font></font></font></p></li><li style=\"box-sizing: inherit;\"><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Peringatan ini akan dihapuskan apabila selama 2 (dua) bulan yang bersangkutan tidak melakukan pelanggaran</font></font></font></p></li><li style=\"box-sizing: inherit;\"><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Bila dalam masa hukuman melakukan pelanggaran kembali, maka statusnya meningkat menjadi SP 3</font></font></font></p></li></ul><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><br style=\"box-sizing: inherit;\"></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\"><span style=\"box-sizing: inherit; font-weight: bolder;\">SP 3</span></font></font></font></p><p style=\"box-sizing: inherit; margin-bottom: 0.02in; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; line-height: 16px;\"><font color=\"#202527\" style=\"box-sizing: inherit;\"><font face=\"Arial, sans-serif\" style=\"box-sizing: inherit;\"><font style=\"box-sizing: inherit; font-size: 10pt;\">Jika Karyawan yang mendapatkan SP 3, silahkan mengundurkan diri ( resign ).</font></font></font></p><p align=\"justify\" style=\"box-sizing: inherit; margin-bottom: 0in; line-height: 16px;\"><br style=\"box-sizing: inherit; text-align: justify; background-color: rgb(233, 237, 242);\"></p>', '', '2025-05-05 21:22:55', '2025-05-05 21:22:55', NULL, NULL, 26);
